// ─────────────────────────────────────────────────────────────────────────────
// CHAPTER 1: Nature and Scope of Physical Geography
// ─────────────────────────────────────────────────────────────────────────────
const ss1_level1: TieredMCQ[] = [
    { id: "ss1-l1-q1", level: 1, question: "Physical Geography studies:", options: ["Human settlements and cultures", "Natural environment and physical features of the Earth", "Political boundaries and governance", "Economic activities of societies"], correctAnswer: 1, explanation: "Physical Geography is a branch of Geography that studies the natural environment — landforms, climate, soils, water bodies, and biosphere." },
    { id: "ss1-l1-q2", level: 1, question: "The term 'Geography' was first coined by:", options: ["Ptolemy", "Aristotle", "Eratosthenes", "Strabo"], correctAnswer: 2, explanation: "Eratosthenes (276–194 BC), the Greek scholar, coined the term 'Geography' from 'geo' (earth) and 'graphos' (description)." },
    { id: "ss1-l1-q3", level: 1, question: "Which of the following is a major branch of Physical Geography?", options: ["Economic Geography", "Geomorphology", "Political Geography", "Population Geography"], correctAnswer: 1, explanation: "Geomorphology (study of landforms) is a major branch of Physical Geography. Economic and Political Geography are branches of Human Geography." },
    { id: "ss1-l1-q4", level: 1, question: "Systematic Geography approach was introduced by:", options: ["Karl Ritter", "Alexander Von Humboldt", "Eratosthenes", "Hecataeus"], correctAnswer: 1, explanation: "Alexander Von Humboldt (1769–1859) developed the Systematic Geography approach — studying one phenomenon globally before identifying spatial patterns." },
    { id: "ss1-l1-q5", level: 1, question: "Regional Geography approach was developed by:", options: ["Alexander Von Humboldt", "Eratosthenes", "Karl Ritter", "Richard Hartshorne"], correctAnswer: 2, explanation: "Karl Ritter (1779–1859) developed the Regional Geography approach — dividing the world into regions and studying all phenomena within each region." },
    { id: "ss1-l1-q6", level: 1, question: "The study of soils and their properties is called:", options: ["Hydrology", "Pedology", "Ecology", "Biogeography"], correctAnswer: 1, explanation: "Pedology is the scientific study of soils, including their physical and chemical properties, formation, and spatial distribution." },
    { id: "ss1-l1-q7", level: 1, question: "Climatology is:","options": ["Study of climatic changes only", "Scientific study of climate and its spatial variation", "Study of weather on a day-to-day basis", "Study of ocean temperatures"], "correctAnswer": 1, "explanation": "Climatology is a branch of physical geography concerned with the scientific study of climate, including its patterns, causes, and effects." },
    { id: "ss1-l1-q8", level: 1, question: "The study of water on and below the Earth's surface is:", options: ["Pedology", "Oceanography", "Hydrology", "Geology"], correctAnswer: 2, explanation: "Hydrology studies the distribution, movement, and properties of water (lakes, rivers, ground water, precipitation)." },
    { id: "ss1-l1-q9", level: 1, question: "Which of the following is NOT a branch of Physical Geography?", options: ["Geomorphology", "Climatology", "Historical Geography", "Oceanography"], correctAnswer: 2, explanation: "Historical Geography is a branch of Human Geography. Physical Geography includes Geomorphology, Climatology, Oceanography, Pedology, and Biogeography." },
    { id: "ss1-l1-q10", level: 1, question: "Biogeography studies:", options: ["Political distribution of living organisms", "Spatial distribution of living organisms and their interaction with environment", "Human impact on biodiversity only", "Classification of species"], correctAnswer: 1, explanation: "Biogeography is concerned with the spatial distribution of plants and animals and their interaction with the physical environment." },
    { id: "ss1-l1-q11", level: 1, question: "The physical environment of the Earth consists of:", options: ["Only the lithosphere", "Lithosphere, atmosphere, and hydrosphere only", "Lithosphere, atmosphere, hydrosphere, and biosphere", "Only the atmosphere and hydrosphere"], correctAnswer: 2, explanation: "The physical environment comprises 4 major spheres: Lithosphere (rocks/land), Atmosphere (air), Hydrosphere (water), and Biosphere (life)." },
    { id: "ss1-l1-q12", level: 1, question: "Which sub-field of Physical Geography deals with the study of oceans?", options: ["Hydrology", "Pedology", "Oceanography", "Glaciology"], correctAnswer: 2, explanation: "Oceanography studies the physical characteristics, movements, and life forms of the world's oceans and seas." },
    { id: "ss1-l1-q13", level: 1, question: "The concept of 'Environmental Determinism' states that:", options: ["Humans control the environment", "Human culture is controlled and determined by the physical environment", "Environment and humans exist independently", "Technology overcomes all environmental constraints"], correctAnswer: 1, explanation: "Environmental Determinism argues that physical environment shapes and controls human behavior, culture, and development." },
    { id: "ss1-l1-q14", level: 1, question: "The concept of 'Possibilism' was associated with:", options: ["Ratzel and Semple", "Brunhes and Vidal de la Blache", "Humboldt and Ritter", "Ptolemy and Strabo"], correctAnswer: 1, explanation: "Possibilism, which argues that humans have choices within environmental constraints, was championed by French geographers like Vidal de la Blache and Jean Brunhes." },
    { id: "ss1-l1-q15", level: 1, question: "The scope of Physical Geography includes study of which of the following?", options: ["Administrative systems", "Natural hazards, landforms, climate, and ecosystems", "Economic policies of nations", "Population migration patterns"], correctAnswer: 1, explanation: "Physical Geography covers landforms, climate, natural hazards, ecosystems, soils, and water bodies — all components of the natural environment." },
];

const ss1_level2: TieredMCQ[] = [
    { id: "ss1-l2-q1", level: 2, question: "Consider the following statements:\n1. Physical Geography studies only the lithosphere.\n2. The four spheres of the Earth's physical environment are mutually interdependent.\n3. Human activities are influencing the physical environment while the environment also affects human activities.\n\nWhich are correct?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2, and 3"], correctAnswer: 1, explanation: "Statement 1 is wrong — Physical Geography covers all four spheres. Statements 2 and 3 are correct. The four spheres are interdependent and the human-environment relationship is two-way." },
    { id: "ss1-l2-q2", level: 2, question: "Assertion (A): Physical Geography is called the 'mother of all sciences'.\nReason (R): Physical Geography integrates knowledge from geology, meteorology, ecology, hydrology, and pedology to understand the Earth's surface.\n\nSelect the correct answer:", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], correctAnswer: 0, explanation: "Physical Geography is indeed called the mother science as it draws from and integrates multiple natural sciences. R correctly explains why A is true." },
    { id: "ss1-l2-q3", level: 2, question: "The fundamental difference between Environmental Determinism and Possibilism is:", options: ["Determinism studies only climate; Possibilism studies all spheres", "Determinism gives primacy to nature over humans; Possibilism reverses this — humans have choices within natural limits", "Determinism is European in origin; Possibilism is American", "There is no difference — both argue the same thing"], correctAnswer: 1, explanation: "Environmental Determinism (Ratzel, Semple) argues that nature dictates human behavior. Possibilism (Vidal de la Blache) counters that humans possess free will and can adapt/modify their environment within certain limits." },
    { id: "ss1-l2-q4", level: 2, question: "Physical Geography provides the 'stage' upon which human drama is played. This analogy suggests:\n1. The physical environment sets the background conditions for human activities.\n2. Humans remain passive actors with no agency.\n3. Physical features like terrain, climate, and resources directly influence settlement, agriculture, and economy.", options: ["1 and 2 only", "1 and 3 only", "2 and 3 only", "1, 2, and 3"], correctAnswer: 1, explanation: "Statements 1 and 3 are correct. The analogy suggests the physical environment creates the context (not absolute control) for human activity. Statement 2 is wrong — humans are not passive." },
    { id: "ss1-l2-q5", level: 2, question: "Which of the following interdisciplinary connections are correctly matched?\n1. Geomorphology ↔ Geology\n2. Climatology ↔ Meteorology\n3. Biogeography ↔ Ecology\n4. Pedology ↔ Political Science\n\nSelect the correct pair:", options: ["1, 2, and 3 only", "2, 3, and 4 only", "1 and 4 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "Geomorphology connects with Geology (Earth's crust), Climatology with Meteorology (weather), Biogeography with Ecology (living organisms and environment). Pedology has no connection with Political Science." },
    { id: "ss1-l2-q6", level: 2, question: "The interdependence of Lithosphere, Atmosphere, Hydrosphere, and Biosphere is best demonstrated by which example?", options: ["Air pollution reduces visibility in urban areas", "Volcanic eruptions influence climate by injecting SO₂ into the stratosphere, affecting precipitation and biotic life", "Earthquakes destroy buildings", "Ocean tides affect lunar movements"], correctAnswer: 1, explanation: "Volcanic eruptions release SO₂ into the stratosphere → forms aerosols → reflects sunlight → lowers surface temperature → affects rainfall patterns → impacts ecosystems. This shows all four spheres interacting." },
    { id: "ss1-l2-q7", level: 2, question: "The 'Neo-Determinism' or 'Stop and Go Determinism' concept was given by:", options: ["Vidal de la Blache", "Griffith Taylor", "Friedrich Ratzel", "Ellen Semple"], correctAnswer: 1, explanation: "Griffith Taylor proposed Neo-Determinism (Stop and Go Determinism) — humans can modify nature but within limits; they must 'stop and check' before proceeding, accepting environmental constraints as optimal." },
    { id: "ss1-l2-q8", level: 2, question: "Consider the following about the scope of Physical Geography in the modern context:\n1. Disaster risk assessment uses geomorphological data.\n2. Climate models are used to predict future food security.\n3. Soil surveys guide agricultural land use planning.\n4. Physical geography has no role in urban planning.\n\nWhich statements are correct?", options: ["1, 2, and 3 only", "2, 3, and 4 only", "1 and 4 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "Physical geography plays a huge role in disaster management, climate modeling, soil science, AND urban planning (terrain, flood zones, microclimates). Statement 4 is wrong." },
    { id: "ss1-l2-q9", level: 2, question: "Humboldt and Ritter are considered founding fathers of modern geography because they:", options: ["Used mathematical models to predict the weather", "Systematically organized geographical knowledge and established geography as a formal academic discipline", "Invented Cartography and GIS", "Developed the theory of plate tectonics"], correctAnswer: 1, explanation: "Both Humboldt (Systematic) and Ritter (Regional) systematically organized geographical knowledge in the 19th century, establishing Geography as a scientific discipline separate from history and philosophy." },
    { id: "ss1-l2-q10", level: 2, question: "The concept that nature offers 'possibilities' and humans select from them based on culture, technology, and economy is called:", options: ["Environmental Determinism", "Possibilism", "Neo-Determinism", "Spatial Analysis"], correctAnswer: 1, explanation: "Possibilism holds that the environment presents opportunities and limitations, but it is human agency (culture, technology, economy) that determines which possibilities are selected and acted upon." },
    { id: "ss1-l2-q11", level: 2, question: "Which of the following best describes the 'holistic approach' in physical geography?", options: ["Studying each landform in isolation", "Studying all components of the physical environment as interrelated parts of a single system", "Only studying human modifications to nature", "Analyzing geographic data statistically"], correctAnswer: 1, explanation: "The holistic approach in Physical Geography means studying the Earth's physical environment as an integrated system where all components (lithosphere, atmosphere, hydrosphere, biosphere) interact with each other." },
    { id: "ss1-l2-q12", level: 2, question: "The utility of Physical Geography in contemporary society includes:\n1. Predicting and mitigating natural disasters.\n2. Sustainable use of natural resources.\n3. Evaluating environmental impact of development projects.\n4. Discouraging all forms of human-environment interaction.\n\nWhich are correct?", options: ["1, 2, and 3 only", "2, 3, and 4 only", "1 and 4 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "Physical Geography is very useful in disaster prediction, resource management, and EIA. Statement 4 is wrong — it doesn't discourage interaction, but promotes sustainable interaction." },
    { id: "ss1-l2-q13", level: 2, question: "The study of landforms and their evolution over time falls under:", options: ["Climatology", "Pedology", "Geomorphology", "Oceanography"], correctAnswer: 2, explanation: "Geomorphology specifically studies landforms, their origin, classification, and the geologic forces that shape them over time." },
    { id: "ss1-l2-q14", level: 2, question: "Which of the following is the most accurate description of 'Glaciology'?", options: ["Study of ocean floor topography", "Scientific study of glaciers and ice sheets, their movement and impact on landscape", "Study of periglacial zones only", "Study of past climates using ice cores only"], correctAnswer: 1, explanation: "Glaciology is the study of glaciers, ice sheets, and ice caps — including their formation, movement, distribution, and effects on landscape and sea level." },
    { id: "ss1-l2-q15", level: 2, question: "Physical Geography's importance for UPSC is because it:\n1. Covers the natural context for all socioeconomic issues.\n2. Explains distribution of natural resources tested in GS papers.\n3. Forms the base for understanding Indian Polity.\n4. Provides framework for understanding environment-based current affairs.\n\nWhich are correct?", options: ["1, 2, and 4 only", "2, 3, and 4 only", "1 and 3 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "Physical Geography is crucial for UPSC GS-1 and GS-3 (environment, natural resources, disasters, location). Statement 3 is wrong — Indian Polity is not based on Physical Geography." },
];

const ss1_level3: TieredMCQ[] = [
    { id: "ss1-l3-q1", level: 3, question: "With reference to the neo-determinist perspective called 'Stop and Go Determinism', consider the following:\n1. It holds that the environment sets absolute limits on human development.\n2. Humans can proceed against nature at their own peril.\n3. Griffith Taylor used Australia's geography to demonstrate that ignoring environmental limits leads to failure.\n\nHow many of the above statements are correct?", options: ["Only one", "Only two", "All three", "None"], correctAnswer: 2, explanation: "All three are correct. Neo-determinism allows human agency but warns that ignoring environmental limits leads to failure. Taylor used Australian examples to show that ignoring climate limits in interior colonization was ill-advised." },
    { id: "ss1-l3-q2", level: 3, question: "The 'Dualism' in Geography, debated since the time of Kant and Humboldt, refers primarily to the tension between:\n1. Physical vs. Human Geography\n2. Systematic vs. Regional approaches\n3. Determinism vs. Possibilism\n4. Quantitative vs. Qualitative methods\n\nWhich are the TWO most historically fundamental dualisms?", options: ["1 and 2 only", "2 and 3 only", "3 and 4 only", "1 and 4 only"], correctAnswer: 0, explanation: "The two most foundational dualisms in Geography are: (i) Physical vs. Human Geography (what to study?), and (ii) Systematic vs. Regional approaches (how to organize knowledge?). These predate the quantitative revolution." },
    { id: "ss1-l3-q3", level: 3, question: "Consider the concept of 'Geosophy' introduced by John Kirtland Wright:\nAssertion (A): Geosophy studies the geographical knowledge of any and all people, not just geographers.\nReason (R): Geographic imaginations of farmers, merchants, and travellers are equally valid objects of geographic study.\n\nThis concept is best associated with which tradition in Geography?", options: ["Quantitative Revolution", "Positivism", "Humanistic Geography", "Physical Determinism"], correctAnswer: 2, explanation: "Geosophy is associated with Humanistic Geography, which values subjective human experiences, perceptions, and imaginations of space and place, not just objective scientific measurements." },
    { id: "ss1-l3-q4", level: 3, question: "Assertion (A): The boundaries between Physical and Human Geography have become increasingly blurred in the 21st century.\nReason (R): Climate change, urban heat islands, and anthropogenic landscape changes represent phenomena that are simultaneously physical and human.\n\nSelect the correct answer:", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], correctAnswer: 0, explanation: "Global warming, urban heat islands, and deforestation-induced landscape changes all have both physical processes and human causes simultaneously — blurring the traditional divide." },
    { id: "ss1-l3-q5", level: 3, question: "The concept of 'Naturalization of Humans and Humanization of Nature' in Geography refers to:", options: ["Humans becoming part of nature with no cultural identity", "The mutual modification — humans reshape nature through culture/technology while nature shapes human societies through climate/terrain", "Only the environmental impact of humans on biodiversity", "The process of deforestation and desertification"], correctAnswer: 1, explanation: "This concept from Vidal de la Blache describes the deep interpenetration: nature is modified by human culture (humanization of nature) while human societies are shaped by their physical environment (naturalization of humans)." },
    { id: "ss1-l3-q6", level: 3, question: "Which of the following scholars is MOST associated with the 'Landscape School' in Geography, which focused on how human activity transforms physical landscapes into cultural landscapes?", options: ["Richard Hartshorne", "Carl Sauer", "Friedrich Ratzel", "Griffith Taylor"], correctAnswer: 1, explanation: "Carl Sauer's 'Morphology of Landscape' (1925) is the foundational text of the Landscape School. He studied how human cultures transform natural landscapes over time into distinctive cultural landscapes." },
    { id: "ss1-l3-q7", level: 3, question: "In UPSC GS Paper 1, 'Distribution of Key Natural Resources' is examined in the context of Physical Geography. Which of the following BEST explains why the distribution of coal is linked to Physical Geography?", options: ["Coal is distributed based on government policy decisions", "Coal deposits are remnants of ancient forests preserved by geological processes — their location is determined by tectonic history and ancient climate zones", "Coal distribution depends on commodity futures markets", "Coal is uniformly distributed globally"], correctAnswer: 1, explanation: "Coal is formed from carboniferous forests over millions of years. Its geographic distribution reflects Carboniferous-age climate zones and subsequent tectonic burial/uplift — making it fundamentally a Physical Geography topic." },
    { id: "ss1-l3-q8", level: 3, question: "Match the philosopher/geographer with their primary contribution to Geography:\n1. Eratosthenes → A. Developed systematic approach\n2. Humboldt → B. First to use 'Geography' as a term\n3. Kant → C. Organized geography as a university discipline\n4. Ritter → D. Developed regional approach\n\nSelect correct matching:", options: ["1-B, 2-A, 3-C, 4-D", "1-A, 2-D, 3-B, 4-C", "1-B, 2-C, 3-A, 4-D", "1-C, 2-B, 3-D, 4-A"], correctAnswer: 0, explanation: "Eratosthenes coined the term Geography. Humboldt developed Systematic approach. Kant organized Geography as a university subject at Königsberg. Ritter developed the Regional approach." },
    { id: "ss1-l3-q9", level: 3, question: "The 'Quantitative Revolution' in Geography (1950s–1970s) sought to make Geography more 'scientific' by:\n1. Replacing all fieldwork with mathematical models.\n2. Applying statistical and mathematical tools to geographic phenomena.\n3. Challenging the ideographic (uniqueness-focused) regional approach with nomothetic (law-seeking) methods.\n4. Eliminating all concepts of space and place.\n\nWhich are correct?", options: ["2 and 3 only", "1, 2, and 3 only", "1 and 4 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "The Quantitative Revolution applied statistical tools (correct) and sought universal laws over unique regional descriptions (nomothetic vs ideographic, correct). It did NOT eliminate all fieldwork or concepts of space." },
    { id: "ss1-l3-q10", level: 3, question: "Which of the following BEST represents the current paradigm in Physical Geography regarding human-environment relationship?", options: ["Pure environmental determinism — nature controls all", "Pure possibilism — humans have unlimited freedom", "Critical Physical Geography — integrating physical processes with social power structures and environmental justice", "Quantitative Revolution — only statistical models matter"], correctAnswer: 2, explanation: "Contemporary Physical Geography has evolved toward 'Critical Physical Geography' — integrating rigorous physical science with human dimensions: who controls resources, whose environments are degraded, and how power shapes environmental risk." },
];

