// CHAPTER 2: Origin of the Earth
// ─────────────────────────────────────────────────────────────────────────────
const ss2_level1: TieredMCQ[] = [
    { id: "ss2-l1-q1", level: 1, question: "The Big Bang Theory was proposed to explain:", options: ["Formation of the Indian subcontinent", "The origin and expansion of the Universe", "The formation of the Earth's core", "The origin of life on Earth"], correctAnswer: 1, explanation: "The Big Bang Theory explains the origin of the Universe from a singular dense point approximately 13.7–13.8 billion years ago, followed by continuous expansion." },
    { id: "ss2-l1-q2", level: 1, question: "The age of the Earth is approximately:", options: ["4.6 million years", "4.6 billion years", "13.7 billion years", "10 million years"], correctAnswer: 1, explanation: "The Earth is approximately 4.6 billion years old, formed from solar nebula material orbiting the young Sun." },
    { id: "ss2-l1-q3", level: 1, question: "The Nebular Hypothesis was originally proposed by:", options: ["Otto Schmidt", "Immanuel Kant", "James Jeans", "Harold Jeffreys"], correctAnswer: 1, explanation: "The Nebular Hypothesis was first proposed by Immanuel Kant in 1755 and later revised by mathematician Laplace in 1796." },
    { id: "ss2-l1-q4", level: 1, question: "Planets are classified into two groups: Terrestrial and Jovian. The Terrestrial planets are:", options: ["Jupiter, Saturn, Uranus, Neptune", "Mercury, Venus, Earth, Mars", "Earth, Mars, Jupiter, Saturn", "Venus, Earth, Saturn, Uranus"], correctAnswer: 1, explanation: "Terrestrial (inner/rocky) planets are Mercury, Venus, Earth, and Mars. Jovian (outer/gas giant) planets are Jupiter, Saturn, Uranus, and Neptune." },
    { id: "ss2-l1-q5", level: 1, question: "The 'Big Splat' theory explains the origin of:", options: ["The Asteroid Belt", "The Earth's Moon", "The continent of Gondwana", "The Solar System"], correctAnswer: 1, explanation: "The Giant Impact Hypothesis (Big Splat) proposes that Earth's Moon formed when a Mars-sized body collided with the early Earth, ejecting debris that coalesced into the Moon." },
    { id: "ss2-l1-q6", level: 1, question: "The process by which planets formed by accumulation of material is called:", options: ["Differentiation", "Accretion", "Degassing", "Sublimation"], correctAnswer: 1, explanation: "Accretion is the process by which small bodies (planetesimals) collide and stick together, gradually building up a planet." },
    { id: "ss2-l1-q7", level: 1, question: "Pluto was reclassified as a 'Dwarf Planet' by the International Astronomical Union in:", options: ["2000", "2003", "2006", "2010"], correctAnswer: 2, explanation: "In August 2006, the IAU reclassified Pluto as a 'dwarf planet' due to its inability to clear its orbital neighborhood — a key criterion for a full planet." },
    { id: "ss2-l1-q8", level: 1, question: "Lighter elements like Silicon and Oxygen are concentrated in which part of Earth?", options: ["Inner Core", "Outer Core", "Mantle", "Crust"], correctAnswer: 3, explanation: "Through differentiation, lighter elements (Si, O, Al) rose to form the crust and upper mantle, while heavier elements (Fe, Ni) sank to form the core." },
    { id: "ss2-l1-q9", level: 1, question: "The early Earth's primordial atmosphere consisted mainly of:", options: ["Oxygen and Nitrogen", "Hydrogen and Helium", "Carbon Dioxide and Nitrogen", "Methane and Ammonia"], correctAnswer: 1, explanation: "The Earth's initial primordial atmosphere was hydrogen and helium (like the solar nebula). These were stripped away by solar wind, and a secondary atmosphere developed through degassing." },
    { id: "ss2-l1-q10", level: 1, question: "The process by which gases escaped from the Earth's hot interior to form the early atmosphere is called:", options: ["Condensation", "Differentiation", "Degassing", "Accretion"], correctAnswer: 2, explanation: "Degassing is the process by which volcanic activity released trapped gases (water vapor, CO₂, N₂, SO₂) from the Earth's interior to form the secondary atmosphere." },
    { id: "ss2-l1-q11", level: 1, question: "The 'Steady State Theory' was proposed by:", options: ["Edwin Hubble", "Hoyle", "Otto Schmidt", "Carl Weizascar"], correctAnswer: 1, explanation: "Fred Hoyle proposed the Steady State Theory as an alternative to the Big Bang Theory, suggesting the Universe looks the same at all times — matter is continuously created." },
    { id: "ss2-l1-q12", level: 1, question: "The asteroid belt is located between:", options: ["Earth and Mars", "Mars and Jupiter", "Jupiter and Saturn", "Saturn and Uranus"], correctAnswer: 1, explanation: "The main asteroid belt lies between the orbits of Mars and Jupiter. It consists of rocky debris left over from the formation of the solar system." },
    { id: "ss2-l1-q13", level: 1, question: "Life is estimated to have first evolved on Earth approximately:", options: ["4.6 billion years ago", "4.0 billion years ago", "3.8 billion years ago", "500 million years ago"], correctAnswer: 2, explanation: "Scientific evidence (fossil records) suggests that life began evolving approximately 3,800 million (3.8 billion) years ago in the early oceans." },
    { id: "ss2-l1-q14", level: 1, question: "Which of the following gas, when removed from oceans through condensation, caused atmospheric temperatures to decrease and stabilize?", options: ["Nitrogen", "Oxygen", "Carbon Dioxide", "Hydrogen"], correctAnswer: 2, explanation: "Early oceans dissolved CO₂ from the atmosphere. This reduced the greenhouse effect, lowering temperatures and allowing more condensation — a stabilizing feedback." },
    { id: "ss2-l1-q15", level: 1, question: "Edwin Hubble's observation about the Universe in 1920 was that:", options: ["The Universe is static and unchanging", "Galaxies are moving towards each other", "Distant galaxies are moving away — the Universe is expanding", "The Sun is not at the center of the Universe"], correctAnswer: 2, explanation: "In 1920, Edwin Hubble using the Doppler effect showed that distant galaxies are receding (red shift) — providing key evidence for the expanding universe hypothesis (Big Bang)." },
];

const ss2_level2: TieredMCQ[] = [
    { id: "ss2-l2-q1", level: 2, question: "Consider the following statements about the Nebular Hypothesis:\n1. It was originally proposed by Immanuel Kant in 1755.\n2. Laplace revised it to explain how planets formed from rings of matter around the Sun.\n3. It was proven completely accurate by modern astronomy.\n\nWhich are correct?", options: ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2, and 3"], correctAnswer: 0, explanation: "Kant (1755) and Laplace (1796) both proposed versions of the Nebular Hypothesis. However, it was largely rejected/modified in the 20th century — statement 3 is incorrect. The modern solar nebula theory is different from the original." },
    { id: "ss2-l2-q2", level: 2, question: "Assertion (A): Terrestrial planets are rocky and dense while Jovian planets are gaseous giants.\nReason (R): Terrestrial planets formed close to the Sun where heat prevented gas condensation; Jovian planets formed in cold outer regions where gas could condense.\n\nSelect the correct answer:", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], correctAnswer: 0, explanation: "The composition difference between terrestrial and Jovian planets is directly explained by their formation location relative to the Sun — too hot for gases near the Sun (Terrestrial zone), cold enough beyond the frost line (Jovian zone)." },
    { id: "ss2-l2-q3", level: 2, question: "The three stages in the evolution of the Earth's atmosphere in correct chronological order are:", options: ["Degassing → Loss of primordial atmosphere → Modification by living organisms", "Loss of primordial atmosphere → Degassing → Modification by living organisms", "Modification by living organisms → Degassing → Loss of primordial atmosphere", "Degassing → Modification by living organisms → Loss of primordial atmosphere"], correctAnswer: 1, explanation: "Stage 1: Solar wind stripped away the primordial H/He atmosphere. Stage 2: Degassing from the hot interior created a secondary CO₂/N₂/water vapor atmosphere. Stage 3: Photosynthesis by living organisms added oxygen and modified the atmosphere." },
    { id: "ss2-l2-q4", level: 2, question: "Consider these statements about planet formation:\n1. Stars form from clouds of gas and dust (nebulae).\n2. Planetesimals form when material condenses through cohesion.\n3. Planets form when planetesimals collide and accrete.\n4. All planets have the same chemical composition as their host star.\n\nWhich are correct?", options: ["1, 2, and 3 only", "2, 3, and 4 only", "1 and 4 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "Statements 1, 2, and 3 correctly describe the planet formation sequence. Statement 4 is wrong — planets have different compositions from stars. Rocky planets are iron/silicon-rich while stars are hydrogen/helium-rich." },
    { id: "ss2-l2-q5", level: 2, question: "The process of 'Differentiation' within the early Earth led to:", options: ["The formation of the Moon", "Separation of Earth material into concentric layers based on density", "The beginning of plate tectonics", "The formation of the first oceans"], correctAnswer: 1, explanation: "Differentiation refers to the separation of Earth's materials by density as the planet was molten — heavy iron and nickel sank to the core while lighter silicates rose to form the mantle and crust." },
    { id: "ss2-l2-q6", level: 2, question: "The 'Goldilocks Zone' or 'Habitable Zone' refers to:", options: ["The asteroid belt between Mars and Jupiter", "The orbital distance from a star where liquid water can exist on a planet's surface", "The zone within a galaxy with stable orbits", "The region where comets originate"], correctAnswer: 1, explanation: "The Goldilocks Zone is the range of distances from a star where surface temperatures allow liquid water to exist — neither too hot nor too cold for life as we know it." },
    { id: "ss2-l2-q7", level: 2, question: "Why is the Big Bang Theory considered the most widely accepted theory for the origin of the Universe?\n1. It explains the observed expansion of the Universe (Cosmic Microwave Background Radiation).\n2. It accurately predicts the observed abundance of light elements (H, He).\n3. It was proposed by the oldest known astronomer.\n4. It requires no mathematics to understand.", options: ["1 and 2 only", "2 and 3 only", "1, 2, and 4 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "The Big Bang is supported by: (1) the Hubble expansion (CMB radiation), (2) predicted abundances of H and He matching observations. The age of proposer or simplicity are not scientific criteria." },
    { id: "ss2-l2-q8", level: 2, question: "The formation of the Moon approximately 4.44 billion years ago through the 'Giant Impact Hypothesis' has which of the following implications for early Earth?\n1. It re-melted the outer layers of Earth.\n2. It mixed Earth's mantle composition.\n3. It contributed to a second phase of differentiation.\n4. It immediately stabilized Earth's axial tilt permanently.", options: ["1, 2, and 3 only", "2, 3, and 4 only", "1 and 4 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "The giant impact re-melted Earth's surface, mixed the mantle, and triggered a second phase of differentiation. Statement 4 is incorrect — while the Moon stabilizes Earth's tilt somewhat, it was not immediately or permanently stabilized." },
    { id: "ss2-l2-q9", level: 2, question: "The Cosmic Microwave Background (CMB) radiation is significant because it:", options: ["Is produced by modern stars and galaxies", "Is the 'afterglow' of the Big Bang — heat radiation from the early Universe now cooled to microwave wavelengths", "Causes aurora borealis", "Is produced by black holes"], correctAnswer: 1, explanation: "CMB is the thermal radiation left over from the early Universe (~380,000 years after the Big Bang). Its nearly uniform temperature (~2.7K) across the sky is strong evidence for the Big Bang model." },
    { id: "ss2-l2-q10", level: 2, question: "Consider the formation of early oceans on Earth:\n1. Water vapor released through degassing condensed as the Earth cooled.\n2. Comets and asteroids may have delivered additional water.\n3. Early oceans were neutral in pH, similar to modern oceans.\n4. The dissolution of CO₂ in early oceans made them slightly acidic.\n\nWhich are correct?", options: ["1, 2, and 4 only", "2, 3, and 4 only", "1 and 3 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "Early oceans formed from degassed water vapor and additional water from comets/asteroids. Dissolved CO₂ made early oceans acidic (carbonic acid), not neutral — Statement 3 is incorrect." },
    { id: "ss2-l2-q11", level: 2, question: "A light-year measures:", options: ["The age of a star in years", "The distance light travels in one year (~9.46 trillion km)", "The brightness of a star", "The speed of expansion of the Universe"], correctAnswer: 1, explanation: "A light-year is a unit of distance equal to the distance light travels in one year — approximately 9.46 × 10¹² km (9.46 trillion km). It is not a unit of time." },
    { id: "ss2-l2-q12", level: 2, question: "The difference between Chamberlain-Moulton's 'Planetesimal Hypothesis' and the Nebular Hypothesis is:", options: ["Both propose the same mechanism", "Planetesimal Hypothesis proposed small solid bodies accreted, while Nebular Hypothesis proposed direct planetary formation from gas rings", "Planetesimal Hypothesis explains life's origin while Nebular explains planet formation", "There is no difference"], correctAnswer: 1, explanation: "The Planetesimal Hypothesis (Chamberlain-Moulton, 1900) proposed a wandering star pulled material from the Sun → planetesimals formed → accreted into planets. The Nebular Hypothesis proposed planets formed directly from cooling gas rings." },
    { id: "ss2-l2-q13", level: 2, question: "Oxygen in the Earth's atmosphere increased significantly due to:", options: ["Volcanic eruptions releasing oxygen", "Photosynthesis by ancient cyanobacteria and plants", "Chemical weathering of rocks releasing oxygen", "Cosmic ray bombardment splitting water molecules"], correctAnswer: 1, explanation: "While photolysis (UV splitting water molecules) added some oxygen, the majority came from photosynthesis — particularly the Great Oxidation Event 2.4 billion years ago driven by cyanobacteria." },
    { id: "ss2-l2-q14", level: 2, question: "Assertion (A): The inner planets have no significant rings while the outer planets have prominent ring systems.\nReason (R): Rings require low-density material (ice, rock) which can only persist in the cold outer solar system far from the Sun's heat.\n\nSelect the correct answer:", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], correctAnswer: 0, explanation: "Inner planets lack rings because the Sun's stronger gravity would destabilize such structures, and solar radiation would sublimate icy ring material. Outer cold regions preserve ice and rock in ring systems." },
    { id: "ss2-l2-q15", level: 2, question: "The process of 'Accretion' during planet formation involves:\n1. Gravitational attraction between small solid bodies.\n2. Collision and sticking of planetesimals.\n3. Growth of larger bodies from accumulation of smaller ones.\n4. Separation of materials by density.\n\nWhich are correct?", options: ["1, 2, and 3 only", "2, 3, and 4 only", "1 and 4 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "Accretion involves gravity attracting, collision, and sticking of planetesimals to form larger bodies. Statement 4 (separation by density) describes Differentiation, not Accretion." },
];

const ss2_level3: TieredMCQ[] = [
    { id: "ss2-l3-q1", level: 3, question: "With reference to the 'Faint Young Sun Paradox', consider the following:\n1. The Sun was ~30% less luminous 3–4 billion years ago than today.\n2. Despite lower solar luminosity, geological evidence shows liquid water existed on early Earth.\n3. This paradox is resolved by a warmer early atmosphere with higher CO₂ and CH₄ concentrations.\n\nHow many are correct?", options: ["Only one", "Only two", "All three", "None"], correctAnswer: 2, explanation: "All three statements are correct. The Faint Young Sun Paradox (Sagan & Mullen, 1972) is resolved by assuming early Earth had a much stronger greenhouse effect (CO₂, CH₄, N₂O) that compensated for weaker solar output." },
    { id: "ss2-l3-q2", level: 3, question: "The 'Late Heavy Bombardment' (LHB) period, occurring approximately 3.8–4.1 billion years ago, is significant for Earth's geological history because:\n1. It coincides with the earliest evidence of life on Earth.\n2. It caused massive cratering visible on the Moon's surface.\n3. It may have delivered organic compounds and water to early Earth.\n4. It increased Earth's atmospheric oxygen.\n\nWhich are correct?", options: ["1, 2, and 3 only", "2, 3, and 4 only", "1 and 4 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "LHB corresponds with earliest life evidence (controversial), definitely caused lunar cratering, and may have delivered organics/water via comets/asteroids. It did NOT increase oxygen — that came later through photosynthesis (~2.4 Bya). Statement 4 is wrong." },
    { id: "ss2-l3-q3", level: 3, question: "Assertion (A): The Earth's Moon is unusually large relative to its host planet compared to moons of other planets.\nReason (R): This large relative size is explained by the Giant Impact Hypothesis, which proposes formation from a massive collision rather than gravitational capture or co-accretion.\n\nSelect the correct answer:", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], correctAnswer: 0, explanation: "The Moon is extremely large relative to Earth (1/4 Earth's size) — larger than the moons of Jupiter and Saturn relative to their planets. The Giant Impact Hypothesis best explains this anomaly." },
    { id: "ss2-l3-q4", level: 3, question: "The composition of exoplanet atmospheres is being studied to detect 'biosignatures'. Which combination of gases, if found together in an exoplanet's atmosphere, would most strongly suggest the presence of life?", options: ["CO₂ and N₂", "O₂ (or O₃) and CH₄ simultaneously", "H₂ and He", "SO₂ and CO"], correctAnswer: 1, explanation: "O₂ and CH₄ should not coexist in equilibrium without continuous replenishment — they react chemically. Detecting both simultaneously is a strong biosignature, as it suggests active biological processes maintaining both gases." },
    { id: "ss2-l3-q5", level: 3, question: "Consider the following regarding Stellar Evolution and its relevance to Earth's future:\n1. The Sun will exhaust hydrogen in its core in approximately 5 billion years.\n2. The Sun will then expand into a Red Giant, possibly engulfing Earth.\n3. Before becoming a Red Giant, the Sun will briefly explode as a Supernova.\n4. Increasing Solar luminosity over next 1 billion years may pose a threat to Earth's habitability.\n\nWhich are correct?", options: ["1, 2, and 4 only", "2, 3, and 4 only", "1 and 3 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "The Sun (~1 solar mass) will NOT supernova — it's too small. Supernovae occur with massive stars. Statements 1, 2, and 4 are correct. Increasing solar brightness over next billion years may push Earth out of the habitable zone even before the Red Giant phase." },
    { id: "ss2-l3-q6", level: 3, question: "The 'Snowball Earth' hypothesis proposes that Earth was entirely (or nearly entirely) frozen multiple times between 700–650 million years ago. Which of the following is a proposed mechanism for Earth's escape from this frozen state?", options: ["A massive asteroid impact", "Volcanic CO₂ emissions building up under the ice until greenhouse warming broke the ice cycle", "A sudden increase in solar luminosity", "Migration of continents to the equator"], correctAnswer: 1, explanation: "During Snowball Earth, volcanic outgassing continued under ice caps, building CO₂ without weathering to remove it. Eventually CO₂ reached levels causing intense greenhouse warming that melted all ice rapidly." },
    { id: "ss2-l3-q7", level: 3, question: "The 'Red Shift' observed in spectral lines of distant galaxies demonstrates:\n1. That galaxies are receding due to the expansion of space itself (cosmological redshift).\n2. This is distinct from Doppler redshift caused by a moving source.\n3. The farther a galaxy, the faster it appears to recede (Hubble's Law).\n4. Red Shift proves that the Big Bang originated at a specific point in space.\n\nWhich statements are correct?", options: ["1, 2, and 3 only", "2, 3, and 4 only", "1 and 4 only", "1, 2, 3, and 4"], correctAnswer: 0, explanation: "Cosmological redshift (stretching of light by expanding space) is distinct from simple Doppler shift. Hubble's Law (v = H₀d) is correct. Statement 4 is wrong — the Big Bang occurred everywhere simultaneously, not at a specific point in space." },
    { id: "ss2-l3-q8", level: 3, question: "The 'Chandrasekhar Limit' (1.4 solar masses) is relevant to understanding stellar remnants. Match correctly:\n1. Star < 1.4 solar masses → A. White Dwarf\n2. Star between 1.4 and ~3 solar masses → B. Neutron Star\n3. Star > ~3 solar masses → C. Black Hole", options: ["1-A, 2-B, 3-C", "1-B, 2-A, 3-C", "1-A, 2-C, 3-B", "1-C, 2-B, 3-A"], correctAnswer: 0, explanation: "Stars below the Chandrasekhar Limit → White Dwarf. Between 1.4–3 solar masses → Neutron Star (supernova collapse). Above ~3 solar masses → Black Hole. Sequence 1-A, 2-B, 3-C is correct." },
    { id: "ss2-l3-q9", level: 3, question: "Which of the following chemical elements were produced in the Big Bang itself (primordial nucleosynthesis)?", options: ["Carbon, Nitrogen, Oxygen", "Iron, Nickel, Cobalt", "Hydrogen, Helium, trace Lithium and Beryllium", "Silicon, Magnesium, Sulfur"], correctAnswer: 2, explanation: "Primordial nucleosynthesis (first 3 minutes after Big Bang) produced hydrogen (75%), helium (25%), and trace amounts of lithium and beryllium. All heavier elements were forged in stellar interiors or supernova explosions." },
    { id: "ss2-l3-q10", level: 3, question: "Assertion (A): The Earth is the densest planet in the Solar System.\nReason (R): Earth has the highest proportion of iron-nickel core relative to its total mass compared to other planets.\n\nSelect the correct answer:", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], correctAnswer: 0, explanation: "Earth is the densest planet (5.51 g/cm³). This is because Earth has a large, differentiated iron-nickel core. While other rocky planets also have iron cores, Earth's proportion is highest and its exact formation and differentiation produced the greatest average density." },
];

