// ─────────────────────────────────────────────────────────────────────────────
// CHAPTER 4: Continents and Ocean Floors
// Standard: 30 L1 (Easy) + 30 L2 (Moderate) + 30 L3 (Tough/Current Affairs) = 90 Qs
// ─────────────────────────────────────────────────────────────────────────────
const ss4_l1: TieredMCQ[] = [
    { id:"ss4-l1-1", level:1, question:"How many major continents are there on Earth?", options:["5","6","7","8"], correctAnswer:2, explanation:"Earth has 7 continents: Asia, Africa, North America, South America, Antarctica, Europe, and Australia." },
    { id:"ss4-l1-2", level:1, question:"Which is the largest continent by area?", options:["Africa","North America","Asia","Antarctica"], correctAnswer:2, explanation:"Asia covers about 44.6 million km², making it the largest continent, comprising about 30% of Earth's land area." },
    { id:"ss4-l1-3", level:1, question:"Which is the smallest continent?", options:["Europe","Antarctica","Australia","South America"], correctAnswer:2, explanation:"Australia (Oceania) is the smallest continent with an area of about 7.7 million km²." },
    { id:"ss4-l1-4", level:1, question:"Which ocean is the largest?", options:["Atlantic","Arctic","Indian","Pacific"], correctAnswer:3, explanation:"The Pacific Ocean is the largest, covering more area than all land masses combined." },
    { id:"ss4-l1-5", level:1, question:"The theory of Continental Drift was proposed by:", options:["Harry Hess","Arthur Holmes","Alfred Wegener","J. Tuzo Wilson"], correctAnswer:2, explanation:"Alfred Wegener proposed Continental Drift in 1912, suggesting all continents were once joined as Pangaea." },
    { id:"ss4-l1-6", level:1, question:"What was the name of Wegener's supercontinent?", options:["Laurasia","Gondwana","Pangaea","Tethys"], correctAnswer:2, explanation:"Pangaea (meaning 'all land') was Wegener's proposed single landmass that existed ~300 million years ago." },
    { id:"ss4-l1-7", level:1, question:"The ocean that separates Africa from the Americas is:", options:["Pacific","Indian","Arctic","Atlantic"], correctAnswer:3, explanation:"The Atlantic Ocean lies between Africa/Europe and the Americas." },
    { id:"ss4-l1-8", level:1, question:"The deepest point on Earth is the Mariana Trench, located in the:", options:["Atlantic Ocean","Indian Ocean","Pacific Ocean","Arctic Ocean"], correctAnswer:2, explanation:"The Mariana Trench in the western Pacific is about 11,034 m deep at the Challenger Deep." },
    { id:"ss4-l1-9", level:1, question:"Gondwana included which of these landmasses?", options:["North America and Europe","South America, Africa, India, Antarctica, Australia","Asia and North America","Europe and Asia"], correctAnswer:1, explanation:"Gondwana was the southern supercontinent comprising South America, Africa, India, Antarctica, and Australia." },
    { id:"ss4-l1-10", level:1, question:"The Mid-Atlantic Ridge is a:", options:["Deep ocean trench","Underwater mountain range","Subduction zone","Continental shelf"], correctAnswer:1, explanation:"The Mid-Atlantic Ridge is an underwater mountain chain running the length of the Atlantic Ocean." },
    { id:"ss4-l1-11", level:1, question:"Continental shelves are characterized by:", options:["Very deep waters","Shallow waters and gentle slope","Steep cliffs","Active volcanoes"], correctAnswer:1, explanation:"Continental shelves are gently sloping, shallow (0–200 m) submerged margins of continents." },
    { id:"ss4-l1-12", level:1, question:"What is the average depth of the oceans?", options:["1,000 m","2,000 m","3,800 m","6,000 m"], correctAnswer:2, explanation:"The average ocean depth is approximately 3,800 metres (3.8 km)." },
    { id:"ss4-l1-13", level:1, question:"Sea floor spreading was proposed by:", options:["Alfred Wegener","J. Tuzo Wilson","Harry Hess","Arthur Holmes"], correctAnswer:2, explanation:"Harry Hess proposed seafloor spreading in 1960-62, explaining how new ocean crust is formed at mid-ocean ridges." },
    { id:"ss4-l1-14", level:1, question:"Laurasia was composed of which present-day landmasses?", options:["South America, Africa, India","North America, Europe, Asia","Antarctica, Australia","South America, Europe"], correctAnswer:1, explanation:"Laurasia was the northern part of Pangaea comprising North America, Europe, and Asia." },
    { id:"ss4-l1-15", level:1, question:"The Tethys Sea was located between:", options:["Two oceans","Laurasia and Gondwana","Two islands","Pacific plates"], correctAnswer:1, explanation:"Tethys was the ancient ocean that separated Laurasia in the north from Gondwana in the south." },
    { id:"ss4-l1-16", level:1, question:"The ocean floor is divided into:", options:["2 divisions","3 divisions","4 divisions","5 divisions"], correctAnswer:2, explanation:"Ocean floor: Continental Shelf, Continental Slope, Continental Rise, Deep Ocean Floor (Abyssal plain)." },
    { id:"ss4-l1-17", level:1, question:"Abyssal plains are:", options:["Mountainous regions","Flat deep ocean floor","Shallow continental areas","Volcanic islands"], correctAnswer:1, explanation:"Abyssal plains are vast, flat regions of deep ocean floor at 3,000–6,000 m depth." },
    { id:"ss4-l1-18", level:1, question:"Which continent has no permanent human settlement?", options:["Arctic","Antarctica","Greenland","Siberia"], correctAnswer:1, explanation:"Antarctica has research stations but no permanent indigenous population." },
    { id:"ss4-l1-19", level:1, question:"The Indian Ocean is bounded on the north by:", options:["Europe","Asia","Africa","Antarctica"], correctAnswer:1, explanation:"Asia (specifically the Indian subcontinent) forms the northern boundary of the Indian Ocean." },
    { id:"ss4-l1-20", level:1, question:"Submarine canyons are mostly found on:", options:["Abyssal plains","Mid-ocean ridges","Continental shelves and slopes","Ocean trenches"], correctAnswer:2, explanation:"Submarine canyons are steep-sided valleys cut into continental shelves and slopes." },
    { id:"ss4-l1-21", level:1, question:"The Pacific Ocean contains about what percentage of world's ocean water?", options:["28%","46%","52%","60%"], correctAnswer:2, explanation:"The Pacific Ocean holds approximately 52% of the world's ocean water." },
    { id:"ss4-l1-22", level:1, question:"Seamounts are:", options:["Islands above water","Submerged volcanic mountains","Ocean trenches","Continental shelves"], correctAnswer:1, explanation:"Seamounts are underwater volcanic mountains that don't reach the ocean surface." },
    { id:"ss4-l1-23", level:1, question:"Which ocean has no land boundary on one side?", options:["Atlantic","Indian","Arctic","Southern"], correctAnswer:3, explanation:"The Southern Ocean (around Antarctica) has no continental land on the south side — it circles Antarctica." },
    { id:"ss4-l1-24", level:1, question:"Continental drift evidence includes:", options:["Similar rock structures on opposite continents","Ocean tides","El Niño","Monsoon patterns"], correctAnswer:0, explanation:"Wegener cited identical geological formations and fossils on opposite shores of the Atlantic as evidence." },
    { id:"ss4-l1-25", level:1, question:"The Challenger Deep is approximately how deep?", options:["7,000 m","9,000 m","11,000 m","15,000 m"], correctAnswer:2, explanation:"Challenger Deep in Mariana Trench is ~11,034 m, the deepest known point." },
    { id:"ss4-l1-26", level:1, question:"Guyots are:", options:["Active volcanoes","Flat-topped seamounts","Island chains","Ocean trenches"], correctAnswer:1, explanation:"Guyots are flat-topped seamounts whose peaks were eroded by wave action when they were above sea level." },
    { id:"ss4-l1-27", level:1, question:"Which fossil was found on both sides of the Atlantic, supporting Wegener?", options:["Tyrannosaurus","Mesosaurus","Triceratops","Mammoth"], correctAnswer:1, explanation:"Mesosaurus fossils were found in South America and Africa, impossible if they were always separate." },
    { id:"ss4-l1-28", level:1, question:"The continental slope connects:", options:["Two continents","Continental shelf to abyssal plain","Two oceans","Seamounts to trenches"], correctAnswer:1, explanation:"Continental slope is the steep descent from the continental shelf edge to the deeper ocean floor." },
    { id:"ss4-l1-29", level:1, question:"Which ocean is shrinking due to plate movement?", options:["Atlantic","Pacific","Indian","Arctic"], correctAnswer:1, explanation:"The Pacific Ocean is shrinking as the Pacific Plate subducts under surrounding plates." },
    { id:"ss4-l1-30", level:1, question:"The Atlantic Ocean is:", options:["Shrinking","Stable","Growing","Disappearing"], correctAnswer:2, explanation:"The Atlantic is growing as the Mid-Atlantic Ridge spreads new ocean floor outward." },
];

const ss4_l2: TieredMCQ[] = [
    { id:"ss4-l2-1", level:2, question:"Consider: 1. Magnetic striping on ocean floor 2. Fossil distribution across continents 3. Similar mountain chains across oceans. Which support Sea Floor Spreading?", options:["1 only","1 and 3 only","1, 2 and 3","2 and 3 only"], correctAnswer:0, explanation:"Magnetic striping (paleomagnetism) directly supports seafloor spreading. Fossils support continental drift; mountain chains support both." },
    { id:"ss4-l2-2", level:2, question:"Wegener's hypothesis was initially rejected primarily because:", options:["His maps were wrong","He could not explain the force that moved continents","He was not a geologist","He ignored fossil evidence"], correctAnswer:1, explanation:"Wegener lacked a credible mechanism — the force needed to move continents — which was only explained later by plate tectonics." },
    { id:"ss4-l2-3", level:2, question:"Sea floor spreading explains the age of ocean rocks as:", options:["Oldest near ridges, youngest at edges","Same age throughout","Youngest near ridges, oldest near trenches","Random distribution"], correctAnswer:2, explanation:"New crust forms at ridges; older crust is pushed outward and eventually subducted at trenches. So youngest rocks are at ridges." },
    { id:"ss4-l2-4", level:2, question:"The concept of 'Isostasy' in the context of continents means:", options:["Continents float on denser mantle","Continents sink slowly","Oceans are heavier than continents","All land is the same density"], correctAnswer:0, explanation:"Isostasy describes the gravitational equilibrium where lighter continental crust 'floats' on denser mantle rock." },
    { id:"ss4-l2-5", level:2, question:"Which correctly describes the Exclusive Economic Zone (EEZ)?", options:["200 km from coast","200 nautical miles from baseline","100 nautical miles","Unlimited ocean area"], correctAnswer:1, explanation:"Under UNCLOS, a country's EEZ extends 200 nautical miles from its coastline baseline." },
    { id:"ss4-l2-6", level:2, question:"The sediment on deep ocean floor is called:", options:["Regolith","Pelagic sediment","Glacial till","Laterite"], correctAnswer:1, explanation:"Pelagic sediments include fine particles that slowly settle from the water column in deep ocean basins." },
    { id:"ss4-l2-7", level:2, question:"The concept of 'Wilson Cycle' refers to:", options:["Volcanic eruption cycles","Opening and closing of ocean basins over geological time","Annual monsoon cycles","Ice age periodicity"], correctAnswer:1, explanation:"The Wilson Cycle describes how ocean basins open (rifting) and close (subduction) over hundreds of millions of years." },
    { id:"ss4-l2-8", level:2, question:"Hydrothermal vents in the ocean floor are associated with:", options:["Trenches","Seamounts","Mid-ocean ridges","Continental shelves"], correctAnswer:2, explanation:"Hydrothermal vents occur where water seeps into ocean crust at ridges and is heated by magma, creating mineral-rich hot water." },
    { id:"ss4-l2-9", level:2, question:"Coral reefs are primarily found in which ocean zone?", options:["Abyssal zone","Hadal zone","Photic zone (shallow tropical)","Midnight zone"], correctAnswer:2, explanation:"Corals need sunlight (photic zone) and warm shallow water, typically found in tropical latitudes." },
    { id:"ss4-l2-10", level:2, question:"Pangaea broke up approximately:", options:["100 million years ago","200 million years ago","400 million years ago","50 million years ago"], correctAnswer:1, explanation:"Pangaea began breaking up approximately 200 million years ago in the Triassic period." },
    { id:"ss4-l2-11", level:2, question:"The Hawaiian Islands are formed by:", options:["Subduction","Mid-ocean ridge","Hot spot volcanism","Continental collision"], correctAnswer:2, explanation:"Hawaii sits over a mantle hot spot; as the Pacific Plate moves, new islands form sequentially over the hot spot." },
    { id:"ss4-l2-12", level:2, question:"Paleomagnetism evidence for seafloor spreading involves:", options:["Ancient animal fossils","Patterns of normal and reversed magnetism in ocean crust","Old maps","Ocean temperature records"], correctAnswer:1, explanation:"As new crust forms at ridges, iron minerals align with Earth's magnetic field, recording alternating normal/reversed stripes." },
    { id:"ss4-l2-13", level:2, question:"The continental rise is formed primarily by:", options:["Lava flows","Turbidity current deposits at base of slope","Erosion of ridges","Ice melt"], correctAnswer:1, explanation:"Continental rise consists of accumulated sediment transported down the slope by turbidity currents." },
    { id:"ss4-l2-14", level:2, question:"Why are ocean trenches found at the edges of the Pacific, not the center?", options:["Pacific is too wide","Subduction occurs at plate boundaries at the edges","Trenches prefer cold water","Ocean currents push them out"], correctAnswer:1, explanation:"Trenches mark convergent plate boundaries where oceanic plates subduct under others — mostly at Pacific margins." },
    { id:"ss4-l2-15", level:2, question:"The UNCLOS treaty establishes which ocean zone for scientific research beyond EEZ?", options:["Territorial sea","Contiguous zone","High Seas (international waters)","Extended Continental Shelf"], correctAnswer:2, explanation:"Beyond 200 NM, the High Seas are international waters open to all nations under UNCLOS." },
    { id:"ss4-l2-16", level:2, question:"'Ring of Fire' surrounding the Pacific is associated with:", options:["Hot spots only","Only earthquakes","Volcanoes and earthquakes at subduction zones","Hurricanes"], correctAnswer:2, explanation:"The Ring of Fire is a seismically and volcanically active zone around the Pacific Plate boundaries." },
    { id:"ss4-l2-17", level:2, question:"Average salinity of ocean water is approximately:", options:["25 ppt","35 ppt","45 ppt","15 ppt"], correctAnswer:1, explanation:"Average ocean salinity is 35 parts per thousand (ppt), though it varies by region." },
    { id:"ss4-l2-18", level:2, question:"Thermocline is:", options:["A layer of constant temperature","A layer where temperature decreases rapidly with depth","A warm surface current","The ocean floor temperature"], correctAnswer:1, explanation:"The thermocline is the layer between surface and deep ocean where temperature drops sharply with increasing depth." },
    { id:"ss4-l2-19", level:2, question:"Ocean ridges are geologically significant because they:", options:["Absorb CO2","Are sites of new crust creation","Mark continental boundaries","Generate tsunamis only"], correctAnswer:1, explanation:"Mid-ocean ridges are divergent boundaries where new oceanic crust is continuously created by magma." },
    { id:"ss4-l2-20", level:2, question:"Which of these is correctly matched? 1. Mariana Trench – Pacific 2. Puerto Rico Trench – Atlantic 3. Java Trench – Indian Ocean", options:["1 only","1 and 2 only","1, 2, and 3","2 and 3 only"], correctAnswer:2, explanation:"All three are correctly matched to their respective oceans." },
    { id:"ss4-l2-21", level:2, question:"The 'Glacken Theory' relates continental shapes to:", options:["Magnetic poles","Fit of continents matching across oceans","Glacier movement","Monsoon formation"], correctAnswer:1, explanation:"Matching coastlines (especially Africa and South America) were an early clue to Wegener." },
    { id:"ss4-l2-22", level:2, question:"What drives sea floor spreading at mid-ocean ridges?", options:["Moon's gravity","Mantle convection currents","Tidal forces","Solar wind"], correctAnswer:1, explanation:"Heat-driven convection in the mantle carries magma upward at ridges, spreading the ocean floor apart." },
    { id:"ss4-l2-23", level:2, question:"Which ocean has the most submarine volcanoes?", options:["Atlantic","Indian","Pacific","Arctic"], correctAnswer:2, explanation:"The Pacific has the most submarine (underwater) volcanic activity, related to its extensive ridge and subduction zones." },
    { id:"ss4-l2-24", level:2, question:"The process of 'subduction' involves:", options:["Two plates colliding and both rising","One plate diving beneath another into the mantle","Plates sliding horizontally","Plates separating"], correctAnswer:1, explanation:"Subduction occurs when a denser oceanic plate descends beneath a less dense plate at convergent boundaries." },
    { id:"ss4-l2-25", level:2, question:"Why is the Tethys Sea important in understanding Himalayan formation?", options:["It was the source of Himalayan rivers","Its sediments were uplifted to form the Himalayas","It connected Asia to Africa","It caused the monsoon"], correctAnswer:1, explanation:"When India collided with Asia, the Tethys Sea sediments were compressed and thrust upward to form the Himalayas." },
    { id:"ss4-l2-26", level:2, question:"The ocean between India and Africa is called:", options:["Bay of Bengal","Red Sea","Indian Ocean","Arabian Sea"], correctAnswer:2, explanation:"The Indian Ocean lies between Asia/Africa and separates these landmasses." },
    { id:"ss4-l2-27", level:2, question:"Which type of crust is denser — oceanic or continental?", options:["Continental","Oceanic","Both equal","Depends on location"], correctAnswer:1, explanation:"Oceanic crust (basaltic, ~3.0 g/cm³) is denser than continental crust (granitic, ~2.7 g/cm³)." },
    { id:"ss4-l2-28", level:2, question:"The transform fault boundary is associated with:", options:["Mountain building","New crust creation","Plates sliding sideways past each other","Subduction"], correctAnswer:2, explanation:"Transform faults are conservative boundaries where plates slide horizontally — neither creating nor destroying crust." },
    { id:"ss4-l2-29", level:2, question:"Mid-ocean ridges collectively form the:", options:["World's longest river system","World's longest mountain chain","World's deepest trenches","World's largest desert"], correctAnswer:1, explanation:"Connected mid-ocean ridges form the world's longest mountain chain — over 65,000 km." },
    { id:"ss4-l2-30", level:2, question:"Atolls are:", options:["Mountain ranges","Ring-shaped coral reefs around lagoons","Ocean trenches","Volcanic peaks"], correctAnswer:1, explanation:"Atolls form when a volcanic island subsides and a coral reef continues to grow upward, leaving a ring around a central lagoon." },
];

const ss4_l3: TieredMCQ[] = [
    { id:"ss4-l3-1", level:3, question:"Assertion (A): India's continental shelf in the Indian Ocean holds significant strategic value.\nReason (R): UNCLOS allows India to claim mineral and energy resources up to 200 nautical miles as part of its EEZ.", options:["Both A and R true, R explains A","Both true, R doesn't explain A","A true R false","A false R true"], correctAnswer:0, explanation:"India's EEZ includes rich fishing grounds and potential hydrocarbon deposits, directly tied to UNCLOS rights." },
    { id:"ss4-l3-2", level:3, question:"Assertion (A): The opening of Arctic sea routes is linked to continental shelf disputes.\nReason (R): Melting ice exposes potential extended continental shelves rich in hydrocarbons claimed by Russia, Canada, Denmark.", options:["Both true, R explains A","Both true, R doesn't explain A","A true R false","A false R true"], correctAnswer:0, explanation:"Climate change-driven melting has intensified geopolitical competition over Arctic shelf resources under UNCLOS Article 76." },
    { id:"ss4-l3-3", level:3, question:"Which recent event is related to mid-ocean ridge activity?\n1. Increased seismic activity near Iceland (2024)\n2. Formation of new volcanic island near Tonga\nWhich correctly reflect mid-ocean/hotspot ridge processes?", options:["1 only","2 only","Both","Neither"], correctAnswer:2, explanation:"Iceland sits on the Mid-Atlantic Ridge; Tonga islands form from subduction/hotspot – both involve subsurface volcanic processes." },
    { id:"ss4-l3-4", level:3, question:"Consider: The Malabar Exercises (India-USA-Japan-Australia) are conducted in the Indian Ocean. Strategically, this is related to which geographic concept?", options:["Heartland Theory","Sea Power (Mahan's theory)","Rimland Theory","Continental Drift"], correctAnswer:1, explanation:"Alfred Thayer Mahan's Sea Power theory holds that control of key ocean routes determines global power — directly relevant to Indian Ocean strategy." },
    { id:"ss4-l3-5", level:3, question:"Assertion (A): Ocean Acidification is accelerating the erosion of continental shelves.\nReason (R): CO2 absorbed by oceans forms carbonic acid, dissolving carbonate-based sediments on shelves.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Ocean acidification threatens shelf ecosystems (corals, molluscs) whose calcium carbonate structures are dissolved by acidic water." },
    { id:"ss4-l3-6", level:3, question:"The Andaman and Nicobar Islands are an extension of which submerged mountain range?", options:["Western Ghats","Arakan Yoma (Myanmar)","Himalayas","Vindhya Range"], correctAnswer:1, explanation:"A&N Islands are the exposed peaks of a submerged ridge that is the extension of the Arakan Yoma mountains of Myanmar." },
    { id:"ss4-l3-7", level:3, question:"Assertion (A): Deep sea mining is a growing geopolitical flashpoint.\nReason (R): Polymetallic nodules on abyssal plains contain cobalt, manganese, and nickel critical for EV batteries.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Nations and corporations are increasingly competing for deep sea mineral rights as the EV economy demands rare metals." },
    { id:"ss4-l3-8", level:3, question:"India claimed Extended Continental Shelf (ECS) beyond 200 NM under UNCLOS. The basis for this claim is:", options:["Military power","Continuity of continental shelf morphology","Ancient historical claims","Bilateral treaties"], correctAnswer:1, explanation:"Under UNCLOS Article 76, countries can claim ECS up to 350 NM if they can prove geological continuity of their continental shelf." },
    { id:"ss4-l3-9", level:3, question:"Which correctly describes current India-China competition in the Indian Ocean?", options:["India is a naval superpower and China has no presence","'String of Pearls' vs India's 'Necklace of Diamonds' strategy","Both nations cooperate fully","Neither has submarines there"], correctAnswer:1, explanation:"China's 'String of Pearls' (ports network) is countered by India's 'Necklace of Diamonds' — a series of friendly port agreements." },
    { id:"ss4-l3-10", level:3, question:"Assertion (A): Continents are still moving today.\nReason (R): GPS measurements confirm that continents move at rates of a few centimetres per year.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"GPS satellites can now directly measure plate movement — India moves ~5 cm/year northward, for instance." },
    { id:"ss4-l3-11", level:3, question:"Seamount chains like the Lakshadweep-Chagos Ridge provide India with:", options:["Only fishing rights","Strategic positioning in the Indian Ocean and EEZ claims","No advantage","Only tourism potential"], correctAnswer:1, explanation:"Island chains extend India's EEZ significantly and serve as strategic forward positions in the Indian Ocean." },
    { id:"ss4-l3-12", level:3, question:"The 'Blue Economy' concept directly relates to which geographic feature?", options:["Mountain glaciers","Continental shelves and ocean zones","Desert oases","River deltas"], correctAnswer:1, explanation:"Blue Economy focuses on sustainable use of ocean resources — fisheries, minerals, energy, shipping — on continental shelves and EEZs." },
    { id:"ss4-l3-13", level:3, question:"Assertion (A): The Indian Ocean is the world's most strategically important ocean.\nReason (R): About 80% of global seaborne oil trade transits the Indian Ocean.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"The Indian Ocean connects the Persian Gulf oil fields to East Asian and European markets, making it critical for global energy security." },
    { id:"ss4-l3-14", level:3, question:"Deep Submergence Vehicle (DSV) Matsya 6000 (India's) is designed to explore:", options:["The Himalayas","Deep ocean floors up to 6,000 m","The stratosphere","River bottoms"], correctAnswer:1, explanation:"Matsya 6000 is India's deep-sea mining vehicle developed under the Deep Ocean Mission for seabed mineral exploration." },
    { id:"ss4-l3-15", level:3, question:"Which international body governs deep seabed mining beyond national jurisdiction?", options:["WTO","UN Security Council","International Seabed Authority (ISA)","UNESCO"], correctAnswer:2, explanation:"The ISA, established under UNCLOS, regulates exploration and exploitation of mineral resources on the deep seabed." },
    { id:"ss4-l3-16", level:3, question:"Assertion (A): Bengal Fan is one of the world's largest deep-sea fans.\nReason (R): It is formed by massive sediment discharge from the Ganges-Brahmaputra river system.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"The Bengal Fan extends 2,800 km into the Bay of Bengal — the world's largest submarine fan, fed by Himalayan erosion." },
    { id:"ss4-l3-17", level:3, question:"Cold seeps on ocean floors are important for:", options:["Shipping routes","Unique chemosynthetic ecosystems and methane hydrates","Coral reef growth","Navigation"], correctAnswer:1, explanation:"Cold seeps emit methane/hydrogen sulphide, supporting chemosynthetic life and containing methane hydrate deposits." },
    { id:"ss4-l3-18", level:3, question:"Assertion (A): Sea-level rise threatens low-lying Pacific island nations existentially.\nReason (R): These islands are atop ocean floor plates that are not subducting.", options:["Both true, R explains A","Both true, R doesn't explain A","A true R false","A false R true"], correctAnswer:1, explanation:"A is true (nations like Tuvalu face existential threat), but the reason is incorrect — the threat is from melting ice raising sea levels, not plate tectonics." },
    { id:"ss4-l3-19", level:3, question:"The 'Alpha Ridge' in the Arctic Ocean is significant because Russia claims:", options:["It is a natural extension of its continental shelf","It has no minerals","It belongs to the USA","It is part of the Antarctic shelf"], correctAnswer:0, explanation:"Russia claims the Lomonosov/Alpha Ridges are continental shelf extensions under UNCLOS Art 76 to gain Arctic seabed rights." },
    { id:"ss4-l3-20", level:3, question:"Methane hydrates on continental slopes are important as:", options:["Fuel for future but also a climate risk","Only pollution sources","Animal habitats only","Mapping references"], correctAnswer:0, explanation:"Methane hydrates are a potential energy source, but their instability poses a risk of massive methane release — a potent greenhouse gas." },
    { id:"ss4-l3-21", level:3, question:"India's 'Deep Ocean Mission' was launched in:", options:["2015","2019","2021","2023"], correctAnswer:2, explanation:"Deep Ocean Mission was approved by the Government of India in June 2021, with targets including deep-sea mining and ocean climate research." },
    { id:"ss4-l3-22", level:3, question:"Assertion (A): Coral bleaching in the Great Barrier Reef is at a record high.\nReason (R): Ocean warming causes corals to expel their symbiotic algae, losing colour and vitality.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"2024 saw widespread mass bleaching of the Great Barrier Reef; warming seas are the direct trigger for zooxanthellae expulsion." },
    { id:"ss4-l3-23", level:3, question:"The 'Two-Ocean Passage' scenario for India through Suez Canal and Mozambique Channel relates to:", options:["Ocean circulation study","Naval two-front deployment strategy","Fishing routes","Trade winds"], correctAnswer:1, explanation:"India's navy is developing two-ocean capability to project power simultaneously in both western (Arabian Sea/Africa) and eastern (Bay of Bengal/Pacific) ocean fronts." },
    { id:"ss4-l3-24", level:3, question:"The sunken continent 'Zealandia' (Te Riu-a-Māui) is significant because:", options:["It is the 8th continent largely submerged","It is a myth","It is the Pacific Ocean floor","It is another name for Australia"], correctAnswer:0, explanation:"Zealandia is a mostly submerged continental mass (~5% above water as New Zealand), proposed as Earth's 8th continent." },
    { id:"ss4-l3-25", level:3, question:"Assertion (A): The Arctic Ocean will be ice-free in summer by 2050.\nReason (R): Global warming is causing unprecedented Arctic Sea Ice loss, opening new commercial shipping routes.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Scientific projections (IPCC) suggest ice-free Arctic summers by 2050, enabling routes like the Northern Sea Route." },
    { id:"ss4-l3-26", level:3, question:"India's Lakshadweep Islands are biogeographically significant because:", options:["They are volcanic","They are coral atolls with unique marine biodiversity","They have no ecological value","They are part of the Deccan plateau"], correctAnswer:1, explanation:"Lakshadweep's coral atolls host unique marine ecosystems and are under threat from ocean warming and acidification." },
    { id:"ss4-l3-27", level:3, question:"Which correctly uses ocean floor knowledge in disaster preparedness?", options:["Using abyssal plain maps to predict floods","Using bathymetry to model tsunami wave patterns","Using seamounts to predict droughts","Using salinity maps for agriculture"], correctAnswer:1, explanation:"Bathymetric data (ocean depth maps) are crucial for modelling how tsunami waves propagate and their impact on coastlines." },
    { id:"ss4-l3-28", level:3, question:"COMRA (China Ocean Mineral Resources R&D Association) significance relates to:", options:["China's agriculture","China's deep seabed mineral exploration program in international waters","China's river management","China's climate policy"], correctAnswer:1, explanation:"COMRA holds major ISA exploration contracts for polymetallic nodules in the Pacific — part of China's deep-sea strategy." },
    { id:"ss4-l3-29", level:3, question:"Assertion (A): Indian Ocean Dipole (IOD) directly linksto continental geography.\nReason (R): Sea surface temperature differences between the western and eastern Indian Ocean affect monsoon intensity over India.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Positive IOD (warm west, cool east) strengthens Indian monsoon; negative IOD weakens it — ocean-continent interaction at its core." },
    { id:"ss4-l3-30", level:3, question:"The United Nations declared 2021–2030 as:", options:["Decade of the Mountains","Decade of Ocean Science for Sustainable Development","Decade of the Arctic","Global Water Decade"], correctAnswer:1, explanation:"The UN Decade of Ocean Science (2021-2030) aims to transform ocean knowledge for sustainable management." },
];

