// ─────────────────────────────────────────────────────────────────────────────
// CHAPTER 5: Rocks and Minerals — 30 L1 + 30 L2 + 30 L3 = 90 Qs
// ─────────────────────────────────────────────────────────────────────────────
const ss5_l1: TieredMCQ[] = [
    { id:"ss5-l1-1", level:1, question:"Rocks are composed of:", options:["One mineral only","Two or more minerals","Water and soil","Living organisms"], correctAnswer:1, explanation:"Rocks are naturally occurring aggregates of one or more minerals." },
    { id:"ss5-l1-2", level:1, question:"Which rock type forms from cooled magma?", options:["Sedimentary","Metamorphic","Igneous","Organic"], correctAnswer:2, explanation:"Igneous rocks form when magma or lava cools and solidifies." },
    { id:"ss5-l1-3", level:1, question:"Granite is a type of:", options:["Sedimentary","Metamorphic","Extrusive igneous","Intrusive igneous"], correctAnswer:3, explanation:"Granite is a coarse-grained intrusive igneous rock that cooled slowly deep underground." },
    { id:"ss5-l1-4", level:1, question:"Basalt is a type of:", options:["Intrusive igneous","Extrusive igneous","Sedimentary","Metamorphic"], correctAnswer:1, explanation:"Basalt is fine-grained extrusive igneous rock formed from rapid cooling of lava at the surface." },
    { id:"ss5-l1-5", level:1, question:"Sedimentary rocks form from:", options:["Cooling magma","Compressed sediments","Heat and pressure","Volcanic ash"], correctAnswer:1, explanation:"Sedimentary rocks form from compaction and cementation of sediments (sand, silt, organic matter)." },
    { id:"ss5-l1-6", level:1, question:"Coal is an example of:", options:["Igneous rock","Metamorphic rock","Organic sedimentary rock","Chemical sedimentary rock"], correctAnswer:2, explanation:"Coal forms from compressed and altered plant matter — an organic sedimentary rock." },
    { id:"ss5-l1-7", level:1, question:"Limestone is mainly composed of:", options:["Quartz","Silicon","Calcium carbonate","Iron oxide"], correctAnswer:2, explanation:"Limestone is a sedimentary rock primarily made of calcium carbonate (CaCO₃)." },
    { id:"ss5-l1-8", level:1, question:"Metamorphic rocks form due to:", options:["Cooling lava","Deposition of sediments","Heat and pressure","Evaporation"], correctAnswer:2, explanation:"Metamorphic rocks are created when existing rocks are transformed by heat, pressure, or chemical activity." },
    { id:"ss5-l1-9", level:1, question:"Marble is the metamorphic equivalent of:", options:["Granite","Sandstone","Limestone","Shale"], correctAnswer:2, explanation:"Marble forms when limestone is subjected to heat and pressure (metamorphism)." },
    { id:"ss5-l1-10", level:1, question:"The hardest natural mineral is:", options:["Quartz","Feldspar","Diamond","Mica"], correctAnswer:2, explanation:"Diamond (hardness 10 on Mohs scale) is the hardest naturally occurring mineral." },
    { id:"ss5-l1-11", level:1, question:"The softest mineral on Mohs scale is:", options:["Gypsum","Talc","Calcite","Mica"], correctAnswer:1, explanation:"Talc has the lowest hardness rating (1) on the Mohs hardness scale." },
    { id:"ss5-l1-12", level:1, question:"Quartz is chemically:", options:["CaCO₃","SiO₂","Fe₂O₃","Al₂O₃"], correctAnswer:1, explanation:"Quartz (silicon dioxide, SiO₂) is one of the most common minerals in Earth's crust." },
    { id:"ss5-l1-13", level:1, question:"Sandstone is a sedimentary rock composed mainly of:", options:["Clay","Sand grains","Shells","Ice"], correctAnswer:1, explanation:"Sandstone forms from cemented sand-sized mineral particles, mainly quartz." },
    { id:"ss5-l1-14", level:1, question:"Shale is formed from:", options:["Sand","Gravel","Clay and mud","Limestone"], correctAnswer:2, explanation:"Shale is a fine-grained sedimentary rock formed from compacted clay, mud, and silt." },
    { id:"ss5-l1-15", level:1, question:"Which rock type has layers (strata)?", options:["Igneous","Metamorphic","Sedimentary","Plutonic"], correctAnswer:2, explanation:"Sedimentary rocks are characteristically layered (stratified) due to successive deposition." },
    { id:"ss5-l1-16", level:1, question:"Slate is the metamorphic form of:", options:["Limestone","Granite","Shale","Sandstone"], correctAnswer:2, explanation:"Slate forms when shale (clay/mudstone) undergoes low-grade metamorphism." },
    { id:"ss5-l1-17", level:1, question:"Quartzite is the metamorphic form of:", options:["Limestone","Shale","Sandstone","Granite"], correctAnswer:2, explanation:"Quartzite forms when sandstone is subjected to intense heat and pressure." },
    { id:"ss5-l1-18", level:1, question:"Rock cycle describes:", options:["Daily weather patterns","Continuous transformation of rocks from one type to another","Tectonic plate movement only","River erosion"], correctAnswer:1, explanation:"The rock cycle shows how igneous, sedimentary, and metamorphic rocks transform into one another over time." },
    { id:"ss5-l1-19", level:1, question:"Feldspar is the most abundant mineral in:", options:["Ocean floor","Sedimentary rocks","Earth's crust","Earth's core"], correctAnswer:2, explanation:"Feldspar group minerals make up about 60% of Earth's crust." },
    { id:"ss5-l1-20", level:1, question:"Fossils are generally found in:", options:["Igneous rocks","Metamorphic rocks","Sedimentary rocks","All rock types"], correctAnswer:2, explanation:"Fossils form in sedimentary rocks where organisms are buried and preserved in layers." },
    { id:"ss5-l1-21", level:1, question:"Iron ore (Hematite) is a:", options:["Silicate mineral","Oxide mineral","Carbonate mineral","Sulphide mineral"], correctAnswer:1, explanation:"Hematite (Fe₂O₃) is an iron oxide mineral, the primary ore of iron." },
    { id:"ss5-l1-22", level:1, question:"Bauxite is the ore of:", options:["Iron","Copper","Aluminium","Gold"], correctAnswer:2, explanation:"Bauxite is the primary ore of aluminium, composed mainly of aluminium hydroxides." },
    { id:"ss5-l1-23", level:1, question:"The Deccan Plateau of India is made of:", options:["Granite","Basalt (Deccan Traps)","Limestone","Sandstone"], correctAnswer:1, explanation:"The Deccan Traps are one of the largest volcanic features on Earth, made of flood basalt." },
    { id:"ss5-l1-24", level:1, question:"Pumice is notable because it:", options:["Is the hardest rock","Floats on water","Conducts electricity","Is magnetic"], correctAnswer:1, explanation:"Pumice is a highly porous volcanic rock with so many air bubbles it can float on water." },
    { id:"ss5-l1-25", level:1, question:"Diamond and graphite are both forms of:", options:["Silicon","Calcium","Carbon","Aluminium"], correctAnswer:2, explanation:"Diamond and graphite are allotropes of carbon — same element, different crystal structure and properties." },
    { id:"ss5-l1-26", level:1, question:"Evaporite rocks form by:", options:["Volcanic eruption","Evaporation of saline water","Glacial deposition","River flooding"], correctAnswer:1, explanation:"Evaporites (halite/gypsum) form when water evaporates, leaving behind mineral deposits." },
    { id:"ss5-l1-27", level:1, question:"The continental crust is mainly composed of:", options:["Basaltic rocks (SIMA)","Granitic rocks (SIAL)","Iron and nickel","Limestone"], correctAnswer:1, explanation:"Continental crust is predominantly silica-alumina (SIAL) — granitic composition." },
    { id:"ss5-l1-28", level:1, question:"Oceanic crust is mainly composed of:", options:["SIAL","SIMA (silica-magnesia — basaltic)","Limestone","Shale"], correctAnswer:1, explanation:"Oceanic crust is denser basaltic rock (SIMA — silica and magnesium)." },
    { id:"ss5-l1-29", level:1, question:"Chalk is a type of:", options:["Igneous rock","Metamorphic rock","Sedimentary rock","Volcanic rock"], correctAnswer:2, explanation:"Chalk is a soft sedimentary rock made of calcium carbonate from marine organisms." },
    { id:"ss5-l1-30", level:1, question:"Which process converts sedimentary rocks into metamorphic rocks?", options:["Weathering","Deposition","Heat and pressure","Cooling"], correctAnswer:2, explanation:"Heat and pressure (often from tectonic forces or igneous intrusion) metamorphose sedimentary rocks." },
];
const ss5_l2: TieredMCQ[] = [
    { id:"ss5-l2-1", level:2, question:"The Bowen's Reaction Series explains:", options:["Order of mineral crystallization from cooling magma","Rock weathering sequence","Sediment deposition order","Metamorphic grade sequence"], correctAnswer:0, explanation:"Bowen's Reaction Series describes the sequence in which different minerals crystallize as magma cools." },
    { id:"ss5-l2-2", level:2, question:"Which rock has the highest silica content?", options:["Basalt","Gabbro","Granite","Peridotite"], correctAnswer:2, explanation:"Granite is felsic — high in silica (>70%) compared to mafic rocks like basalt (<52%)." },
    { id:"ss5-l2-3", level:2, question:"Consider: 1.Hornfels forms near igneous intrusions 2.Schist forms under regional metamorphism. Which is correct?", options:["1 only","2 only","Both","Neither"], correctAnswer:2, explanation:"Both correct: Hornfels = contact metamorphism; Schist = regional metamorphism with foliation." },
    { id:"ss5-l2-4", level:2, question:"'Cleavage' in minerals refers to:", options:["Breaking along random planes","Breaking along definite crystallographic planes","Colour of the mineral","Shine of the surface"], correctAnswer:1, explanation:"Mineral cleavage is the tendency to break along flat planes determined by crystal structure." },
    { id:"ss5-l2-5", level:2, question:"Oil and natural gas are primarily found in which rock type?", options:["Igneous","Metamorphic","Sedimentary","Plutonic"], correctAnswer:2, explanation:"Hydrocarbons form in organic-rich sedimentary basins and are trapped in porous sedimentary rocks." },
    { id:"ss5-l2-6", level:2, question:"Plagioclase feldspar is a key indicator mineral of:", options:["Basalt and gabbro","Limestone","Coal","Shale"], correctAnswer:0, explanation:"Calcium-rich plagioclase is characteristic of mafic igneous rocks like basalt and gabbro." },
    { id:"ss5-l2-7", level:2, question:"Which is the correct metamorphic grade sequence (low to high)?", options:["Slate→Phyllite→Schist→Gneiss","Gneiss→Schist→Phyllite→Slate","Schist→Slate→Gneiss→Phyllite","Gneiss→Slate→Schist→Phyllite"], correctAnswer:0, explanation:"Slate (low grade) → Phyllite → Schist → Gneiss (high grade) represents increasing metamorphic intensity." },
    { id:"ss5-l2-8", level:2, question:"Kimberlite pipes are geologically important because:", options:["They are the source of diamonds","They cause earthquakes","They are oil reservoirs","They produce marble"], correctAnswer:0, explanation:"Kimberlite pipes are deep volcanic intrusions that bring diamonds from the mantle to the surface." },
    { id:"ss5-l2-9", level:2, question:"Laterite soil formation is linked to which rock weathering process?", options:["Physical/mechanical","Chemical — leaching in tropical humid climate","Biological","Glacial"], correctAnswer:1, explanation:"Laterite forms through intense chemical weathering (leaching) of silica, leaving iron and aluminium oxides." },
    { id:"ss5-l2-10", level:2, question:"Radioactive minerals in rocks are significant for:", options:["Mapping rivers","Absolute age dating (radiometric)","Identifying metamorphic grade","Finding fossils"], correctAnswer:1, explanation:"Radiometric dating uses decay of radioactive isotopes in minerals to calculate absolute rock ages." },
    { id:"ss5-l2-11", level:2, question:"'Stratification' in rocks is primarily a feature of:", options:["Igneous","Metamorphic","Sedimentary","Plutonic"], correctAnswer:2, explanation:"Stratification (layering) is the defining characteristic of sedimentary rocks reflecting episodic deposition." },
    { id:"ss5-l2-12", level:2, question:"India's major iron ore deposits (Jharkhand, Odisha) are found in:", options:["Sedimentary rocks","Archaean metamorphic/BIF formations","Volcanic basalt","Limestone"], correctAnswer:1, explanation:"Indian iron ore deposits are Banded Iron Formations (BIF) — Precambrian metamorphic/sedimentary origin." },
    { id:"ss5-l2-13", level:2, question:"Which property distinguishes metamorphic from igneous rocks?", options:["Crystalline nature","Foliation/banding due to directional pressure","Presence of minerals","Hardness"], correctAnswer:1, explanation:"Foliation (parallel alignment of minerals) is characteristic of regionally metamorphosed rocks due to directional stress." },
    { id:"ss5-l2-14", level:2, question:"Pegmatite is important because:", options:["It is the hardest rock","It contains coarse crystals with rare minerals including gemstones","It forms coral reefs","It is the most common surface rock"], correctAnswer:1, explanation:"Pegmatites form from late-stage magmatic fluids and often contain large crystals of rare and economically valuable minerals." },
    { id:"ss5-l2-15", level:2, question:"The 'parent rock' from which a metamorphic rock forms is called:", options:["Protolith","Paleorock","Matrix","Bedrock"], correctAnswer:0, explanation:"The protolith is the original rock before metamorphism." },
    { id:"ss5-l2-16", level:2, question:"Chalk cliffs (like Dover, UK) are formed from:", options:["Igneous intrusion","Biogenic limestone/chalk sediment","Glacial deposition","Metamorphic uplift"], correctAnswer:1, explanation:"Chalk accumulated from microscopic marine organism shells (coccoliths) in warm shallow Cretaceous seas." },
    { id:"ss5-l2-17", level:2, question:"Geodes are:", options:["Hollow rocks lined with mineral crystals","Solid granite masses","Types of fossils","Volcanic bombs"], correctAnswer:0, explanation:"Geodes are rock cavities lined with inward-projecting crystals, often quartz or calcite." },
    { id:"ss5-l2-18", level:2, question:"Turbidite deposits represent:", options:["Glacial sediments","Rapid deep-water gravity flow deposits","Desert sand deposits","River delta sediments"], correctAnswer:1, explanation:"Turbidites are sedimentary layers deposited by turbidity currents on the deep ocean floor/continental slope." },
    { id:"ss5-l2-19", level:2, question:"India's Gondwana coal is found mainly in:", options:["Sedimentary basins of eastern India","Western Ghats","Himalayan peaks","Deccan Plateau"], correctAnswer:0, explanation:"Gondwana coalfields in Damodar Valley, Mahanadi basin etc. are in Permian-Triassic sedimentary sequences." },
    { id:"ss5-l2-20", level:2, question:"The term 'lithification' refers to:", options:["Rock melting","Converting sediments to rock (compaction + cementation)","Rock metamorphism","Volcanic activity"], correctAnswer:1, explanation:"Lithification is the process by which loose sediments are compacted and cemented into sedimentary rock." },
    { id:"ss5-l2-21", level:2, question:"Charnockite is significant in Indian geology because:", options:["It is found only in Himalayas","It is the oldest Precambrian rock in Peninsular India","It is a recently formed volcanic rock","It contains diamonds"], correctAnswer:1, explanation:"Charnockite is an ancient granulite-facies metamorphic rock forming the basement of Peninsular India." },
    { id:"ss5-l2-22", level:2, question:"Which correctly matches rock type to economic use?\n1. Limestone — cement production\n2. Granite — dimension stone\n3. Shale — oil shale", options:["1 only","1 and 2 only","1, 2, and 3","2 and 3 only"], correctAnswer:2, explanation:"All three are correct economic applications of their respective rock types." },
    { id:"ss5-l2-23", level:2, question:"'Obsidian' is formed when:", options:["Lava cools very slowly","Lava cools extremely rapidly creating volcanic glass","Sandstone is compressed","Limestone is heated"], correctAnswer:1, explanation:"Obsidian is natural volcanic glass created when silica-rich lava cools too fast for crystals to form." },
    { id:"ss5-l2-24", level:2, question:"Index minerals in metamorphic rocks indicate:", options:["Rock colour","Metamorphic grade/temperature-pressure conditions","Age of the rock","Fossil content"], correctAnswer:1, explanation:"Index minerals like chlorite, biotite, garnet, staurolite indicate progressively higher metamorphic grades." },
    { id:"ss5-l2-25", level:2, question:"The Moho discontinuity separates:", options:["Crust from mantle","Mantle from outer core","Inner from outer core","Lithosphere from asthenosphere"], correctAnswer:0, explanation:"The Mohorovičić discontinuity (Moho) is the boundary between Earth's crust and the upper mantle." },
    { id:"ss5-l2-26", level:2, question:"Black soil (Regur) of Maharashtra is derived from:", options:["Granite weathering","Basalt weathering (Deccan Traps)","Limestone","Alluvial deposits"], correctAnswer:1, explanation:"Black cotton soil forms from weathering of Deccan basalt, rich in iron and magnesium, ideal for cotton." },
    { id:"ss5-l2-27", level:2, question:"Which rock is most resistant to chemical weathering?", options:["Limestone","Shale","Quartzite","Marble"], correctAnswer:2, explanation:"Quartzite (recrystallized quartz) is extremely resistant to both chemical and physical weathering." },
    { id:"ss5-l2-28", level:2, question:"Dolomite differs from limestone in that:", options:["It has no calcium","It contains magnesium in addition to calcium carbonate","It is always metamorphic","It does not react to acid"], correctAnswer:1, explanation:"Dolomite is CaMg(CO₃)₂ — calcium magnesium carbonate, unlike pure CaCO₃ limestone." },
    { id:"ss5-l2-29", level:2, question:"'Conglomerate' is a sedimentary rock made of:", options:["Fine clay particles","Rounded pebbles cemented together","Organic plant matter","Chemical precipitates"], correctAnswer:1, explanation:"Conglomerate consists of rounded gravel/pebbles (coarse-grained clasts) cemented in a finer matrix." },
    { id:"ss5-l2-30", level:2, question:"The K-T boundary layer (iridium) is found in:", options:["Granite","Sedimentary strata at Cretaceous-Paleogene boundary","Basalt","Metamorphic gneiss"], correctAnswer:1, explanation:"The iridium-rich K-Pg (K-T) layer in sedimentary rock marks the asteroid impact ~66 Ma ago." },
];
const ss5_l3: TieredMCQ[] = [
    { id:"ss5-l3-1", level:3, question:"Assertion (A): India's geological map shows ancient Precambrian rocks in Peninsular India.\nReason (R): Peninsular India is a stable craton not significantly affected by Himalayan orogeny.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"The Peninsular Indian Shield is among the oldest stable landmasses, shielded from Himalayan folding." },
    { id:"ss5-l3-2", level:3, question:"Which of the following statements about shale gas is correct?\n1. It is extracted from shale rock formations\n2. Hydraulic fracturing (fracking) is the primary extraction method\n3. India has significant shale gas reserves", options:["1 only","1 and 2 only","All three","2 and 3 only"], correctAnswer:2, explanation:"All three are correct. India has shale gas in Cambay, KG basin etc., though extraction faces environmental concerns." },
    { id:"ss5-l3-3", level:3, question:"Assertion (A): Critical minerals like lithium and cobalt are now as strategically important as oil.\nReason (R): EV batteries, solar panels, and defence electronics require these rare minerals found in specific rock formations.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"The energy transition has made critical mineral security a top geopolitical priority for all major powers." },
    { id:"ss5-l3-4", level:3, question:"India's National Critical Minerals Mission targets which deposits?\n1. Lithium in Jammu & Kashmir (Reasi)\n2. Cobalt in Odisha\n3. REEs from monazite coastal sands", options:["1 only","1 and 3 only","All three","2 and 3 only"], correctAnswer:2, explanation:"India discovered lithium in J&K (2023), has cobalt in Odisha, and significant REE in coastal monazite sands." },
    { id:"ss5-l3-5", level:3, question:"Assertion (A): Rare Earth Elements (REEs) are not actually rare in Earth's crust.\nReason (R): They are dispersed and rarely found in concentrated economically viable deposits.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"REEs are abundant in crust but rarely concentrated enough for economical mining — hence the supply bottleneck." },
    { id:"ss5-l3-6", level:3, question:"The Himalayan rocks contain marine fossils because:", options:["The Himalayas were once an ocean","Marine organisms walked up mountains","Fossils were deposited by rivers","They are igneous rocks with mineral impressions"], correctAnswer:0, explanation:"Himalayan rocks were once Tethys Sea sediments; India-Eurasia collision uplifted them, carrying marine fossils." },
    { id:"ss5-l3-7", level:3, question:"Assertion (A): India banned export of beach sand minerals (ilmenite, rutile) in 2024.\nReason (R): These are critical titanium-bearing minerals with strategic aerospace and defence applications.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"India restricted exports to conserve strategic minerals; titanium is critical for aerospace manufacturing." },
    { id:"ss5-l3-8", level:3, question:"Carbon sequestration in basaltic rocks is being explored as climate solution because:", options:["Basalt is the most common rock","Basalt minerals react with CO₂ to form stable carbonate minerals permanently","Basalt is cheap","Basalt is found only in deserts"], correctAnswer:1, explanation:"Basalt contains calcium and magnesium silicates that react with CO₂ to form solid carbonates (mineral trapping)." },
    { id:"ss5-l3-9", level:3, question:"Assertion (A): Lithium found in Salars (salt flats) of South America is in brine form.\nReason (R): Evaporation of ancient lakes in Andean basins concentrated lithium salts in subsurface brines.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"The 'Lithium Triangle' (Bolivia-Chile-Argentina) contains brine lithium in Andean salt flat basins." },
    { id:"ss5-l3-10", level:3, question:"India's Geological Survey of India (GSI) discovery of lithium in Reasi (J&K) is significant because:", options:["It is decorative stone","It can reduce India's 100% lithium import dependency for EV batteries","It will be used for construction","It has no strategic value"], correctAnswer:1, explanation:"India imports all its lithium currently; domestic deposit would transform the EV supply chain and reduce dependence on China." },
    { id:"ss5-l3-11", level:3, question:"Assertion (A): Rock weathering patterns have changed due to climate change.\nReason (R): Warmer, wetter conditions accelerate chemical weathering, altering sediment delivery to rivers and coasts.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Climate change is intensifying chemical weathering rates, affecting river sediment loads and coastal erosion patterns." },
    { id:"ss5-l3-12", level:3, question:"Which mineral is central to the India-China trade tension?\n1. Gallium - used in semiconductors\n2. Germanium - used in fibre optics/chips\n3. Both are controlled by China", options:["1 only","2 only","Both 1 and 2 (China controls both)","Neither"], correctAnswer:2, explanation:"China controls ~80% of global gallium and germanium supply; its export restrictions in 2023 alarmed global tech/defence sectors." },
    { id:"ss5-l3-13", level:3, question:"Assertion (A): Metamorphic rocks in the Himalayas confirm India-Asia collision.\nReason (R): High-pressure granulite and eclogite facies rocks indicate deep crustal burial during continent-continent collision.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Ultra-high-pressure metamorphic minerals (coesite, diamond micro-inclusions) in Himalayan rocks directly record deep subduction during collision." },
    { id:"ss5-l3-14", level:3, question:"Deep sea nodules attracted attention in 2023 due to:", options:["Fishing rights","Rich deposits of cobalt, manganese, nickel for the green energy transition","Navigation hazards","Tsunami risk"], correctAnswer:1, explanation:"Polymetallic nodules on abyssal plains contain critical minerals essential for EV batteries and renewable energy storage." },
    { id:"ss5-l3-15", level:3, question:"Assertion (A): Fracking (hydraulic fracturing) causes induced seismicity.\nReason (R): High-pressure fluid injection into rock formations can reactivate dormant fault planes.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Multiple studies confirm fracking-induced earthquakes in USA, UK, and elsewhere through fault reactivation." },
    { id:"ss5-l3-16", level:3, question:"The 'Snowball Earth' hypothesis relates to rocks because:", options:["All rocks formed during glaciation","Glacial deposits (diamictites) from 700 Ma confirm global glaciation events","Snow makes rocks softer","Mountains were all glaciated"], correctAnswer:1, explanation:"Ancient diamictites (glacial sedimentary rocks) found near the equator support a global glaciation ~700 million years ago." },
    { id:"ss5-l3-17", level:3, question:"India's National Mineral Exploration Policy 2016 aims at:", options:["Banning all mining","Accelerating exploration by opening blocks to private sector","Nationalising all minerals","Ending environmental clearances"], correctAnswer:1, explanation:"NMEP sought to transform India from under-explored to actively explored mineral economy by private sector participation." },
    { id:"ss5-l3-18", level:3, question:"Which statement about REE mining environmental impacts is correct?", options:["REE mining has no environmental cost","Processing REEs produces radioactive thorium waste","REEs are extracted cleanly using water only","REE mines are in uninhabited areas only"], correctAnswer:1, explanation:"REE ore processing involves monazite which contains radioactive thorium — a significant environmental concern." },
    { id:"ss5-l3-19", level:3, question:"Assertion (A): Granite forms the foundation of stable continental platforms.\nReason (R): Granite's low density, rigidity, and chemical stability make it ideal basement rock for ancient shields.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Ancient granite gneiss complexes form cratons — the stable kernels of continents that have not been deformed for billions of years." },
    { id:"ss5-l3-20", level:3, question:"Which is the correct order of increasing metamorphic grade for pelitic rocks?", options:["Slate→Phyllite→Schist→Gneiss","Gneiss→Schist→Slate→Phyllite","Phyllite→Slate→Gneiss→Schist","Schist→Phyllite→Slate→Gneiss"], correctAnswer:0, explanation:"Pelitic (clay-rich) rocks metamorphose in increasing grade: Slate→Phyllite→Schist→Gneiss." },
    { id:"ss5-l3-21", level:3, question:"Carbon stored in sedimentary rocks (carbonate rocks) is called:", options:["Organic carbon pool","Geological/lithospheric carbon pool","Atmospheric pool","Biotic carbon"], correctAnswer:1, explanation:"Sedimentary limestone and dolomite hold the largest geological carbon reservoir — far exceeding atmospheric CO₂." },
    { id:"ss5-l3-22", level:3, question:"Assertion (A): Sand and gravel are among the most mined materials globally.\nReason (R): Construction boom, especially in Asia and Africa, has caused a global 'sand crisis'.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Sand scarcity is a growing crisis — illegal sand mining is depleting rivers and coastlines across the developing world." },
    { id:"ss5-l3-23", level:3, question:"Mineral certification (like Kimberley Process for diamonds) exists to:", options:["Grade mineral quality","Prevent conflict mineral trade financing armed groups","Set prices globally","Control exports to rich countries only"], correctAnswer:1, explanation:"The Kimberley Process Certification Scheme prevents 'blood diamonds' from funding rebel militias in conflict zones." },
    { id:"ss5-l3-24", level:3, question:"India's Mines and Minerals (Development & Regulation) Amendment Act 2021 primarily aimed at:", options:["Banning private sector","Making captive mine blocks transferable and opening 50 blocks for commercial mining","Nationalizing all mines","Increasing mining in forest areas"], correctAnswer:1, explanation:"The 2021 MMDR Amendment liberalized the mining sector, allowing auction of blocks for commercial production without end-use restrictions." },
    { id:"ss5-l3-25", level:3, question:"Which technology is being developed for extracting minerals from mine tailings?", options:["Nuclear energy","Bioleaching using bacteria","Laser mining","Electromagnetic extraction"], correctAnswer:1, explanation:"Bioleaching uses microorganisms to dissolve metals from low-grade ores and tailings, reducing waste and improving recovery." },
    { id:"ss5-l3-26", level:3, question:"Assertion (A): The Eastern Ghats of India are geologically older than the Himalayas.\nReason (R): Eastern Ghats are Precambrian metamorphic ranges, while Himalayas formed in the Cenozoic.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Eastern Ghats are over 1 billion years old Precambrian belts; Himalayas began forming ~50 million years ago." },
    { id:"ss5-l3-27", level:3, question:"Geo-heritage sites are important because:", options:["They are tourist sites only","They represent significant geological formations/processes important for science and education","They are mining zones","They are wildlife sanctuaries"], correctAnswer:1, explanation:"Geological heritage sites like the Lonar crater, Deccan Traps serve as outdoor laboratories for Earth science." },
    { id:"ss5-l3-28", level:3, question:"Assertion (A): Uranium deposits in Jharkhand (Jadugoda) are in metamorphic rocks.\nReason (R): Uranium concentrates in metamorphic-hydrothermal veins and some sedimentary formations.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Jadugoda's uranium is in Proterozoic metamorphic rocks — India's primary uranium source for nuclear energy." },
    { id:"ss5-l3-29", level:3, question:"Which concern about asteroid mining relates directly to mineralogy?", options:["Space temperatures","Metallic asteroids contain iron-nickel and platinum group elements worth trillions","Asteroids have no minerals","Mining will cause meteor showers"], correctAnswer:1, explanation:"M-type asteroids are essentially differentiated metallic cores — rich in platinum group metals (PGMs) and iron-nickel." },
    { id:"ss5-l3-30", level:3, question:"Assertion (A): Ocean floor basalt is being studied for carbon sequestration.\nReason (R): Injecting CO₂ into basaltic ocean crust converts it to solid carbonate minerals within 2 years.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"CarbFix project in Iceland proved CO₂ mineralizes in basalt within 2 years — a permanent sequestration solution." },
];
