// ─────────────────────────────────────────────────────────────────────────────
// CHAPTER 6: Vulcanicity — 30 L1 + 30 L2 + 30 L3 = 90 Qs
// ─────────────────────────────────────────────────────────────────────────────
const ss6_l1: TieredMCQ[] = [
    { id:"ss6-l1-1", level:1, question:"Vulcanicity refers to:", options:["Earthquake activity","All processes by which molten material reaches the crust or surface","River flooding","Glacial melting"], correctAnswer:1, explanation:"Vulcanicity encompasses all magmatic processes — intrusive (plutonism) and extrusive (volcanism)." },
    { id:"ss6-l1-2", level:1, question:"Magma that reaches the Earth's surface is called:", options:["Magma","Lava","Pluton","Batholith"], correctAnswer:1, explanation:"Magma is molten rock below the surface; once it erupts at the surface it is called lava." },
    { id:"ss6-l1-3", level:1, question:"Volcanoes are classified as active, dormant, and:", options:["Passive","Extinct","Shallow","Cold"], correctAnswer:1, explanation:"Active = currently erupting; Dormant = not erupting but could; Extinct = no expected future eruption." },
    { id:"ss6-l1-4", level:1, question:"Which type of volcano has gentle slopes and fluid lava?", options:["Composite/Stratovolcano","Shield volcano","Cinder cone","Caldera"], correctAnswer:1, explanation:"Shield volcanoes (like Hawaii's Mauna Loa) have low-viscosity basaltic lava forming broad, gently sloping domes." },
    { id:"ss6-l1-5", level:1, question:"Stratovolcanoes are made of alternating layers of:", options:["Sand and gravel","Lava and pyroclastic material","Ice and snow","Limestone and granite"], correctAnswer:1, explanation:"Stratovolcanoes (composite volcanoes) are built of alternating layers of lava flows and pyroclastic (ash, cinders) material." },
    { id:"ss6-l1-6", level:1, question:"A caldera is:", options:["A small volcanic cone","Large depression formed by collapse of a volcanic summit","Type of lava","Volcanic gas"], correctAnswer:1, explanation:"A caldera is a large crater formed when the magma chamber beneath a volcano empties and the summit collapses." },
    { id:"ss6-l1-7", level:1, question:"Mount Vesuvius is located in:", options:["Greece","Italy","Spain","Turkey"], correctAnswer:1, explanation:"Mount Vesuvius is an active stratovolcano near Naples, Italy. Its 79 AD eruption buried Pompeii." },
    { id:"ss6-l1-8", level:1, question:"The 'Ring of Fire' refers to:", options:["Equatorial zone","Zone of active volcanoes and earthquakes around the Pacific Ocean","African Rift Valley","Mid-Atlantic Ridge"], correctAnswer:1, explanation:"The Pacific Ring of Fire encircles the Pacific Ocean with ~75% of Earth's volcanoes and 90% of earthquakes." },
    { id:"ss6-l1-9", level:1, question:"Pyroclastic material includes:", options:["Lava flows only","Ash, cinders, bombs ejected during eruptions","River sediments","Chemical deposits"], correctAnswer:1, explanation:"Pyroclastic materials are fragments (ash, lapilli, volcanic bombs) explosively ejected from a volcano." },
    { id:"ss6-l1-10", level:1, question:"A geyser is:", options:["A hot spring that periodically erupts","A small volcano","A type of lava","A volcanic gas vent"], correctAnswer:0, explanation:"Geysers are hot springs where superheated groundwater episodically erupts as jets of water and steam." },
    { id:"ss6-l1-11", level:1, question:"Old Faithful is a famous geyser in:", options:["Iceland","New Zealand","Yellowstone, USA","Japan"], correctAnswer:2, explanation:"Old Faithful in Yellowstone National Park (USA) erupts predictably every ~90 minutes." },
    { id:"ss6-l1-12", level:1, question:"A Solfatara is a:", options:["Shield volcano","Vent emitting sulphurous gases and vapours","Type of earthquake","Deep ocean trench"], correctAnswer:1, explanation:"A solfatara is a fumarole (volcanic vent) that emits sulphurous gases — named after a field near Naples." },
    { id:"ss6-l1-13", level:1, question:"Intrusive volcanic features form:", options:["On the surface","Underground when magma solidifies","In the ocean","In glaciers"], correctAnswer:1, explanation:"Intrusive (plutonic) features form when magma cools and solidifies below the surface without erupting." },
    { id:"ss6-l1-14", level:1, question:"A batholith is:", options:["A small volcanic plug","Largest intrusive igneous body covering hundreds of km²","A type of hot spring","A volcanic island"], correctAnswer:1, explanation:"A batholith is the largest intrusive igneous rock body, often forming the cores of mountain ranges." },
    { id:"ss6-l1-15", level:1, question:"A sill is a:", options:["Vertical igneous intrusion","Horizontal sheet of igneous rock intruded between rock layers","Volcanic crater","Lava tube"], correctAnswer:1, explanation:"A sill is a tabular igneous intrusion that parallels the layering of surrounding rocks." },
    { id:"ss6-l1-16", level:1, question:"A dyke (dike) is a:", options:["Horizontal intrusion","Vertical or steeply inclined igneous sheet cutting across rock layers","Volcanic lake","Hot spring"], correctAnswer:1, explanation:"A dyke is a discordant intrusion that cuts across existing rock structures, typically vertical or steeply inclined." },
    { id:"ss6-l1-17", level:1, question:"Lava tubes form when:", options:["Lava cools everywhere uniformly","Outer lava solidifies while molten lava drains through the interior","Magma intrudes horizontally","Pyroclastic flows cool"], correctAnswer:1, explanation:"Lava tubes are natural tunnels formed by hardening lava around flowing molten lava, which eventually drains out." },
    { id:"ss6-l1-18", level:1, question:"The Deccan Traps in India were formed by:", options:["Normal volcanic eruption","Flood basalt eruption (~65 Ma ago)","Earthquake uplift","Glacial deposition"], correctAnswer:1, explanation:"The Deccan Traps are one of Earth's largest flood basalt provinces, formed ~65 Ma ago possibly linked to the K-Pg extinction." },
    { id:"ss6-l1-19", level:1, question:"Fumaroles are:", options:["Volcanic lakes","Vents emitting gases and steam from volcanic areas","Shield volcanoes","Lava tubes"], correctAnswer:1, explanation:"Fumaroles are openings in Earth's crust, often near volcanoes, that emit steam and volcanic gases." },
    { id:"ss6-l1-20", level:1, question:"Pahoehoe lava has:", options:["Rough, jagged surface","Smooth, ropy surface","Explosive character","Black colour only"], correctAnswer:1, explanation:"Pahoehoe is low-viscosity basaltic lava with a smooth, billowy or ropy surface formed by slow-moving flows." },
    { id:"ss6-l1-21", level:1, question:"Aa lava has:", options:["Smooth surface","Rough, jagged, clinkery surface","High silica content","No eruption"], correctAnswer:1, explanation:"Aa (pronounced 'ah-ah') lava cools faster than pahoehoe, creating a clinker-like, rough, jagged surface." },
    { id:"ss6-l1-22", level:1, question:"Mauna Loa, Hawaii is the world's:", options:["Tallest mountain","Largest shield volcano","Most explosive volcano","Deepest caldera"], correctAnswer:1, explanation:"Mauna Loa is Earth's largest active shield volcano by volume, rising from the ocean floor." },
    { id:"ss6-l1-23", level:1, question:"Krakatau (Krakatoa) is famous for its:", options:["Mild eruptions","Catastrophic 1883 eruption causing global temperature drop","Geyser activity","Diamond mining"], correctAnswer:1, explanation:"The 1883 Krakatau eruption was one of history's deadliest, heard 5,000 km away and causing a global 'volcanic winter'." },
    { id:"ss6-l1-24", level:1, question:"Volcanic soils are generally:", options:["Infertile","Highly fertile due to mineral richness","Sandy","Acidic and unproductive"], correctAnswer:1, explanation:"Weathered volcanic soils (like Andosols) are among the most fertile due to high mineral content from the parent basalt." },
    { id:"ss6-l1-25", level:1, question:"Hot spots are:", options:["Surface volcanoes","Fixed mantle plumes of hot material rising through the crust","Ocean trenches","Earthquake zones"], correctAnswer:1, explanation:"Hot spots are stationary plumes of hot mantle material that form chains of volcanoes as plates move over them." },
    { id:"ss6-l1-26", level:1, question:"The Hawaiian Islands were formed by:", options:["Plate collision","A hot spot (mantle plume)","Mid-ocean ridge","Subduction"], correctAnswer:1, explanation:"The Hawaiian Island chain formed as the Pacific Plate moved northwest over a stationary hot spot." },
    { id:"ss6-l1-27", level:1, question:"A laccolith is:", options:["Vertical dyke","Dome-shaped intrusion that domes up overlying rocks","Ocean hot spot","Volcanic gas cloud"], correctAnswer:1, explanation:"A laccolith is a mushroom-shaped igneous intrusion where magma domes up the overlying strata." },
    { id:"ss6-l1-28", level:1, question:"Volcanic islands are generally formed:", options:["By river deposition","Along mid-ocean ridges and hot spots","By coral growth alone","By glacier action"], correctAnswer:1, explanation:"Volcanic islands form where volcanic activity builds up from submarine eruptions at ridges or hot spots." },
    { id:"ss6-l1-29", level:1, question:"Barren Island (India) is:", options:["An uninhabited island with coral reefs","India's only active volcano, in Andaman & Nicobar Islands","A sandbank in the Bay of Bengal","An island off Goa"], correctAnswer:1, explanation:"Barren Island in the Andaman Sea is India's only confirmed active volcano, last erupted in 2017." },
    { id:"ss6-l1-30", level:1, question:"Narcondam Island (India) is classified as:", options:["Active volcano","Dormant volcano","Coral atoll","Sedimentary island"], correctAnswer:1, explanation:"Narcondam in the Andaman Islands is a dormant volcanic island, contrasting with nearby active Barren Island." },
];
const ss6_l2: TieredMCQ[] = [
    { id:"ss6-l2-1", level:2, question:"Subduction-zone volcanoes are typically:", options:["Shield volcanoes","Stratovolcanoes with explosive, silica-rich magma","Cinder cones","Flood basalts"], correctAnswer:1, explanation:"Subducting oceanic plates release water lowering mantle melting point, creating silica-rich, viscous, explosive andesitic magma forming stratovolcanoes." },
    { id:"ss6-l2-2", level:2, question:"The viscosity of lava controls its eruption style because:", options:["Low viscosity = explosive; High viscosity = gentle flows","High viscosity = explosive because gases cannot escape","Both erupt equally","Viscosity has no effect on eruption"], correctAnswer:1, explanation:"High-viscosity (silica-rich) lava traps volcanic gases; pressure builds until explosive eruption. Low-viscosity basaltic lava lets gases escape gently." },
    { id:"ss6-l2-3", level:2, question:"Pillow lavas form:", options:["On land in deserts","Underwater when lava erupts into the ocean","In ice-filled craters","During explosive eruptions"], correctAnswer:1, explanation:"Pillow lavas are rounded, pillow-shaped basaltic structures formed by rapid quenching of lava erupted on the ocean floor." },
    { id:"ss6-l2-4", level:2, question:"A nuée ardente (pyroclastic surge) is:", options:["Gentle lava flow","Fast-moving avalanche of hot gas, ash, and pyroclastic material","Cold mudflow","Underwater eruption"], correctAnswer:1, explanation:"Nuée ardente (glowing cloud) is a deadly pyroclastic density current — a fast-moving avalanche of hot gas and tephra." },
    { id:"ss6-l2-5", level:2, question:"Lahar is:", options:["Volcanic gas","Fast-moving mudflow of volcanic debris mixed with water","Slow lava flow","Pyroclastic fall"], correctAnswer:1, explanation:"Lahars are volcanic mudflows — eruption melts glaciers/snow or heavy rain mobilises volcanic ash into devastating torrents." },
    { id:"ss6-l2-6", level:2, question:"The 1991 Mount Pinatubo (Philippines) eruption is geologically significant because:", options:["It created a new island","It caused global cooling by injecting SO₂ into the stratosphere","It was the smallest eruption ever","It had no casualties"], correctAnswer:1, explanation:"Pinatubo's 1991 eruption released 20 Mt SO₂, forming sulfate aerosols that cooled global temperatures by ~0.5°C for 2 years." },
    { id:"ss6-l2-7", level:2, question:"Mid-ocean ridge volcanism produces predominantly:", options:["Rhyolite (silica-rich)","Basalt (silica-poor) from decompression melting","Andesite","Pumice"], correctAnswer:1, explanation:"At divergent boundaries, decompression melting of asthenospheric mantle produces MORB (mid-ocean ridge basalt) — silica-poor and fluid." },
    { id:"ss6-l2-8", level:2, question:"Phonolite and trachyte are volcanic rocks associated with:", options:["Convergent boundaries","Continental rift zones and oceanic islands","Mid-ocean ridges","Subduction zones"], correctAnswer:1, explanation:"Phonolite and trachyte are potassium/sodium-rich volcanic rocks typical of continental rifts (like East African Rift) and oceanic hot spots." },
    { id:"ss6-l2-9", level:2, question:"Tephra refers to:", options:["A type of geyser","All fragmented material ejected by a volcano regardless of size","Volcanic gas only","Submarine lava"], correctAnswer:1, explanation:"Tephra is the collective term for all airborne volcanic fragments — from fine ash to large volcanic bombs." },
    { id:"ss6-l2-10", level:2, question:"The Volcanic Explosivity Index (VEI) measures:", options:["Speed of lava flow","Volume of pyroclastic material ejected on a logarithmic scale","Temperature of magma","Depth of magma chamber"], correctAnswer:1, explanation:"VEI is a logarithmic scale (0–8) measuring the volume of erupted material — each step = ~10× more material." },
    { id:"ss6-l2-11", level:2, question:"Toba supervolcano eruption (~74,000 BP) is notable for:", options:["Creating the Pacific Ocean","Causing a volcanic winter that may have nearly caused human extinction","Producing diamonds","Creating the Himalayas"], correctAnswer:1, explanation:"The Toba event (Sumatra) ejected ~2,800 km³ of material, causing a 6-10 year volcanic winter and a possible genetic bottleneck in Homo sapiens." },
    { id:"ss6-l2-12", level:2, question:"Columnar jointing in basalt (like Giant's Causeway) forms due to:", options:["Earthquake fracturing","Contraction cracking as lava cools uniformly","Erosion","Chemical weathering"], correctAnswer:1, explanation:"Columnar jointing forms when basaltic lava cools and contracts uniformly, producing regular hexagonal columns." },
    { id:"ss6-l2-13", level:2, question:"Which of the following pairs is correct?\n1. Réunion Island — hot spot volcanism\n2. Iceland — mid-ocean ridge volcanism\n3. Andes volcanoes — subduction volcanism", options:["1 only","1 and 2 only","All three","2 and 3 only"], correctAnswer:2, explanation:"All three are correct examples of their respective tectonic settings for volcanism." },
    { id:"ss6-l2-14", level:2, question:"India's Barren Island last erupted in:", options:["1991","2017","2005","1883"], correctAnswer:1, explanation:"Barren Island had significant eruptive activity in 2017, making it one of the most recently active volcanoes in South/Southeast Asia." },
    { id:"ss6-l2-15", level:2, question:"A maar is:", options:["A large shield volcano","A shallow, flat-floored volcanic crater formed by phreatic (steam) explosions","A type of batholith","A lava plateau"], correctAnswer:1, explanation:"Maars form when rising magma contacts groundwater, causing violent steam explosions that create wide, shallow craters often filled with lakes." },
    { id:"ss6-l2-16", level:2, question:"The 'volcanic winter' effect is caused by:", options:["Lava blocking sunlight","Sulphur dioxide aerosols in the stratosphere reflecting sunlight","Ash blocking rivers","CO₂ emissions"], correctAnswer:1, explanation:"SO₂ from major eruptions converts to sulphate aerosols in the stratosphere, scattering solar radiation and cooling the Earth for years." },
    { id:"ss6-l2-17", level:2, question:"Subglacial eruptions create:", options:["Lava tubes","Tuyas (table mountains) and jökulhlaup (glacial outburst floods)","Pillars","Normal shield volcanoes"], correctAnswer:1, explanation:"Subglacial eruptions melt overlying ice creating jökulhlaup floods; erupted material forms tuyas — flat-topped volcanic mountains." },
    { id:"ss6-l2-18", level:2, question:"Pompeii was buried by the 79 AD Vesuvius eruption primarily under:", options:["Lava flows","Pyroclastic surges and ash falls","Lahars","Lava tubes"], correctAnswer:1, explanation:"Pompeii was buried under pyroclastic surges and ~4-6m of pumice/ash, not primarily lava flows." },
    { id:"ss6-l2-19", level:2, question:"The East African Rift Valley has volcanoes because:", options:["Subduction occurs there","Continental rifting thins the crust allowing magma to rise","It is a hot spot","It is on the Ring of Fire"], correctAnswer:1, explanation:"The East African Rift System is a divergent boundary where the African plate splits, thinning the crust and enabling volcanism." },
    { id:"ss6-l2-20", level:2, question:"A volcanic neck (plug) is:", options:["A lava flow","Solidified magma in the throat of an extinct volcano exposed by erosion","A caldera","A hot spring"], correctAnswer:1, explanation:"A volcanic neck is the resistant solidified lava that filled the conduit of a former volcano; surrounding material erodes leaving it exposed." },
    { id:"ss6-l2-21", level:2, question:"Phreatomagmatic eruptions occur when:", options:["Two lava flows merge","Rising magma interacts with groundwater or surface water","Magma reaches 1500°C","Gas escapes silently"], correctAnswer:1, explanation:"Phreatomagmatic eruptions result from magma-water interaction — extraordinarily explosive due to sudden steam generation." },
    { id:"ss6-l2-22", level:2, question:"Which volcanic zone of India lies along convergent plate boundary?", options:["Barren Island (subduction-related, Andaman Arc)","Deccan Traps","Lonar crater","Eastern Ghats"], correctAnswer:0, explanation:"Barren Island lies in the Andaman volcanic arc, formed by subduction of the Indian Plate under the Burma microplate." },
    { id:"ss6-l2-23", level:2, question:"The Yellowstone supervolcano sits above:", options:["A subduction zone","A continental hot spot (mantle plume)","A mid-ocean ridge","A transform fault"], correctAnswer:1, explanation:"Yellowstone lies above one of Earth's most powerful hot spots, with a magma chamber that could produce a super-eruption." },
    { id:"ss6-l2-24", level:2, question:"MORB stands for:", options:["Mountain-Origin Rock Basalt","Mid-Ocean Ridge Basalt","Mantle-Origin Rounded Basalt","Mid-Ocean Rift Bedrock"], correctAnswer:1, explanation:"MORB (Mid-Ocean Ridge Basalt) is the most abundant lava on Earth, produced by decompression melting at divergent plate boundaries." },
    { id:"ss6-l2-25", level:2, question:"Rhyolite eruptions are more explosive than basalt because:", options:["Rhyolite is hotter","Rhyolite has very high silica content, making it viscous and trapping gases","Rhyolite is formed underwater","Rhyolite contains more iron"], correctAnswer:1, explanation:"Rhyolite's high silica content makes it very viscous; trapped volcanic gases build enormous pressure until explosive release." },
    { id:"ss6-l2-26", level:2, question:"Lonar Crater Lake (Maharashtra) is significant because:", options:["It is a volcanic caldera","It is a meteor impact crater (not volcanic) — one of only four confirmed impact craters in basalt worldwide","It is an extinct shield volcano","It is a maar volcano"], correctAnswer:1, explanation:"Lonar is a ~50,000-year-old meteorite impact crater in the Deccan Traps basalt — often mistakenly called volcanic." },
    { id:"ss6-l2-27", level:2, question:"Olivine is significant in igneous petrology because:", options:["It is the hardest mineral","It is the first mineral to crystallize from basaltic magma (Bowen Series)","It forms diamonds","It is found only in granite"], correctAnswer:1, explanation:"Olivine crystallizes first in Bowen's discontinuous reaction series, forming the earliest (highest temperature) mineral in basaltic melts." },
    { id:"ss6-l2-28", level:2, question:"A lopolith is:", options:["A dome-shaped intrusion","A saucer-shaped igneous intrusion concave upward","A vertical dyke swarm","A caldera lake"], correctAnswer:1, explanation:"A lopolith is a large, concave (bowl-shaped) intrusive body, often gigantic — like the Bushveld Complex (South Africa)." },
    { id:"ss6-l2-29", level:2, question:"Continental flood basalts (like Deccan Traps) are linked with:", options:["Ocean trench formation","Mass extinction events — Deccan Traps with K-Pg extinction","Mountain building","Glaciation"], correctAnswer:1, explanation:"The Deccan Traps eruptions (~66 Ma) are hypothesized to have contributed to the mass extinction alongside the Chicxulub asteroid impact." },
    { id:"ss6-l2-30", level:2, question:"Phreatic eruptions are:", options:["The most explosive magmatic eruptions","Steam-driven explosions where magma doesn't directly reach surface but heats groundwater","Cold gas explosions","Underwater basalt eruptions"], correctAnswer:1, explanation:"Phreatic eruptions are purely steam-driven — superheated groundwater flashes to steam but no new magma erupts." },
];
const ss6_l3: TieredMCQ[] = [
    { id:"ss6-l3-1", level:3, question:"Assertion (A): The 2021 La Palma (Canary Islands) eruption lasted 85 days and destroyed 3,000 buildings.\nReason (R): It was a rift eruption along the Cumbre Vieja volcanic ridge, driven by a deep mantle plume beneath the Canary Islands hot spot.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"The 2021 Cumbre Vieja eruption was one of the longest in recorded La Palma history — caused by persistent hot spot magmatism." },
    { id:"ss6-l3-2", level:3, question:"Assertion (A): Iceland sits on both a mid-ocean ridge AND a hot spot.\nReason (R): This double heat source makes Iceland one of the most volcanically active places on Earth with large basaltic eruptions.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Iceland's position on the Mid-Atlantic Ridge above the Iceland Mantle Plume gives it exceptional volcanic output." },
    { id:"ss6-l3-3", level:3, question:"Which of the following about volcanic climate impacts is INCORRECT?", options:["Volcanic SO₂ causes stratospheric cooling","Volcanic CO₂ causes long-term warming over geological time","Mount Pinatubo caused warming of 0.5°C in 1992","Large flood basalts can trigger mass extinctions via CO₂ emissions"], correctAnswer:2, explanation:"Pinatubo caused COOLING of ~0.5°C in 1992-93 (not warming) by injecting SO₂ aerosols into the stratosphere." },
    { id:"ss6-l3-4", level:3, question:"India's vulnerability to volcanic threat primarily relates to:", options:["Deccan Plateau basalt reactivation","Tsunamis triggered by undersea eruptions near Andaman Arc and Indian Ocean hot spots","Mt. Kailash eruption risk","Himalayan rifting"], correctAnswer:1, explanation:"Submarine volcanic activity and associated tsunamis (like 2004 Sumatra) pose the greatest volcano-linked hazard to India's coasts." },
    { id:"ss6-l3-5", level:3, question:"Assertion (A): The Siberian Traps are linked to the Permian-Triassic mass extinction (the 'Great Dying').\nReason (R): Massive SO₂ and CO₂ emissions from flood basalts caused acid rain, ocean acidification, and global warming killing ~96% of marine species.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"The Siberian Traps eruption (~252 Ma) is the leading candidate for causing the largest mass extinction, 'The Great Dying'." },
    { id:"ss6-l3-6", level:3, question:"Consider: There is growing concern about undersea volcanoes (seamounts) because:\n1. They affect submarine cable routes\n2. Their eruptions can trigger tsunamis\n3. They host unique hydrothermal vent ecosystems", options:["1 only","1 and 2 only","All three","2 and 3 only"], correctAnswer:2, explanation:"All three are valid concerns — submarine volcanism has infrastructure, hazard, and biodiversity implications." },
    { id:"ss6-l3-7", level:3, question:"Assertion (A): Volcanic monitoring has become critical for disaster preparedness in India.\nReason (R): Barren Island's proximity to major shipping lanes and the Andaman settlement zone makes eruption monitoring a national security concern.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"NCPOR (Goa) monitors Barren Island as it could disrupt Andaman shipping and threaten settlements via ashfall and associated tsunamis." },
    { id:"ss6-l3-8", level:3, question:"Taal Volcano (Philippines) erupted in 2020. Its unique danger is:", options:["Extreme lava speed","It is an island within a lake within an island — multiple caldera lakes amplify phreatomagmatic explosion risk","High altitude eruption","No evacuation routes"], correctAnswer:1, explanation:"Taal's extraordinary nested caldera structure — volcano island in Taal Lake on Luzon Island — creates extreme phreatomagmatic explosion risk." },
    { id:"ss6-l3-9", level:3, question:"Which is the most accurate statement about the relationship between plate tectonics and volcanism?", options:["All volcanoes occur at plate boundaries","~80% of volcanism occurs at plate boundaries; intraplate hot spots account for remainder","Only subduction zones produce volcanoes","Volcanism only occurs at divergent boundaries"], correctAnswer:1, explanation:"~80% of volcanic activity is plate-boundary related; hot spots (Hawaii, Yellowstone, Réunion) produce the remaining ~20% intraplate volcanism." },
    { id:"ss6-l3-10", level:3, question:"Assertion (A): Volcanic ash grounding of aircraft is a serious modern hazard.\nReason (R): Volcanic ash melts inside jet engines, causing flameout — as demonstrated by the 2010 Eyjafjallajökull eruption that halted European air traffic for 6 days.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"The 2010 Iceland eruption caused the largest disruption of European air travel since WWII, affecting 10 million passengers." },
    { id:"ss6-l3-11", level:3, question:"'Blue zones' of high life expectancy (Okinawa, Sardinia) often coincide with:", options:["Active volcanism","Ancient volcanic soils providing mineral-rich diets","Cold climates","High altitude plains"], correctAnswer:1, explanation:"Nutrient-rich volcanic soils in places like Sardinia and Japanese islands are hypothesized to contribute to longevity through mineral-rich food chains." },
    { id:"ss6-l3-12", level:3, question:"Assertion (A): Carbon capture via enhanced weathering of volcanic basalt is being considered as a climate solution.\nReason (R): Spreading crushed basalt on agricultural land accelerates CO₂ absorption while improving soil fertility.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Enhanced basalt weathering is a promising carbon dioxide removal (CDR) technique with co-benefits for soil health and crop yields." },
    { id:"ss6-l3-13", level:3, question:"Consider the following about the 2022 Hunga Tonga-Hunga Ha'apai eruption:\n1. It generated a tsunami reaching Japan and USA\n2. It caused SO₂ injections into the stratosphere\n3. It triggered a temporary global pressure wave", options:["1 only","1 and 2 only","All three","2 and 3 only"], correctAnswer:2, explanation:"2022 Hunga Tonga was one of the most powerful 21st-century eruptions — its pressure wave circled Earth multiple times and it generated transoceanic tsunamis." },
    { id:"ss6-l3-14", level:3, question:"Assertion (A): India and Mozambique signed an agreement on volcanic monitoring in 2024.\nReason (R): The Comoros Islands and Indian Ocean hot spots pose shared hazards to both countries' EEZ regions.", options:["A true R false","Both true, R explains A","Both true, no explanation","A false, R true"], correctAnswer:2, explanation:"While bilateral monitoring cooperation exists broadly, specific India-Mozambique volcanic monitoring is not verified — this is a distractor requiring critical evaluation." },
    { id:"ss6-l3-15", level:3, question:"Geothermal energy exploitation is most viable near:", options:["Old shield areas","Active volcanic and tectonic zones with high heat flow (Iceland, Kenya, India's Puga Valley)","Desert regions","Polar zones"], correctAnswer:1, explanation:"Geothermal energy requires high subsurface heat — volcanic zones, rift valleys and geothermal fields provide this. India's Puga Valley (J&K) is a priority site." },
    { id:"ss6-l3-16", level:3, question:"Assertion (A): India has identified the Puga Valley (Ladakh) as a priority geothermal energy site.\nReason (R): Puga Valley has hot springs, mud pools and fumaroles indicating shallow geothermal heat flow suitable for power generation.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"ONGC and GSI have studied Puga Valley extensively. India's National Geothermal Energy Mission targets Puga for pilot power plants." },
    { id:"ss6-l3-17", level:3, question:"Which statement about submarine volcanoes is most accurate for UPSC purposes?", options:["They pose no threat to humans","They can form new islands (Surtsey, 1963; Hunga Tonga) and generate tsunamis","Only underwater","They are merely theoretical"], correctAnswer:1, explanation:"Submarine volcanoes create new land (Surtsey Island, Iceland; Home Reef, Tonga) and generate tsunamis — real geopolitical implications for maritime boundaries." },
    { id:"ss6-l3-18", level:3, question:"Assertion (A): Volcanic eruptions in high latitudes can have greater global impact than tropical ones.\nReason (R): Tropical eruptions inject aerosols into both hemispheres, while polar eruptions affect only one hemisphere — making tropical eruptions MORE globally impactful.", options:["Both true; A false: polar eruptions actually have less impact","Both true; A is wrong — tropical eruptions are more impactful","A is false; tropical eruptions are more globally impactful","Both false"], correctAnswer:2, explanation:"Tropical eruptions are MORE globally impactful because stratospheric circulation distributes aerosols globally. Assertion A is incorrect." },
    { id:"ss6-l3-19", level:3, question:"Supervolcano caldera systems (Yellowstone, Toba, Campi Flegrei) are dangerous because:", options:["They have small eruptions only","A super-eruption (VEI 8) could eject >1,000 km³ material causing multi-year global cooling and crop failure","They are near cities only","They create tsunamis only"], correctAnswer:1, explanation:"VEI 8 super-eruptions are civilization-scale events capable of triggering volcanic winters affecting global food security for years." },
    { id:"ss6-l3-20", level:3, question:"Consider: India's National Disaster Management Authority (NDMA) has a specific plan for:", options:["Deccan Traps reactivation","Volcanic hazard from Barren Island and related tsunami risk to Andaman & Nicobar Islands","Himalayan volcanism","Southern Indian volcanism"], correctAnswer:1, explanation:"NDMA's Andaman & Nicobar disaster plan acknowledges volcanic and tsunami hazard from Barren Island and the Andaman subduction arc." },
    { id:"ss6-l3-21", level:3, question:"Assertion (A): Volcanic eruptions contribute to long-term global cooling.\nReason (R): Volcanic CO₂ over millions of years has been outgassed and then absorbed by silicate weathering — part of the carbon-silicate geological thermostat.", options:["Both true, R explains A","A false — volcanoes cause short-term cooling but long-term warming via CO₂ over geological time","Both false","A true, R unrelated"], correctAnswer:1, explanation:"Short-term cooling is from SO₂ aerosols. Long-term geological CO₂ from volcanoes warms the planet; silicate weathering draws it back down — the geological thermostat." },
    { id:"ss6-l3-22", level:3, question:"'Surtseyan' eruption style (named after Surtsey, Iceland, 1963) refers to:", options:["Quiet effusive eruption","Violently explosive eruption from a shallow submarine vent interacting with seawater","Shield lava flows","Continental flood basalt"], correctAnswer:1, explanation:"Surtseyan eruptions are characterised by violent steam explosions when shallow submarine or coastal magma meets water — cinder jets and cauliflower-shaped ash clouds." },
    { id:"ss6-l3-23", level:3, question:"Campi Flegrei (Italy) raised international concern in 2023-24 because:", options:["A major eruption occurred","Ground uplift (bradyseism) accelerated, with swarms of small earthquakes suggesting magma intrusion near the densely populated Naples area","It stopped erupting","It was reclassified as extinct"], correctAnswer:1, explanation:"Campi Flegrei (near Naples, population 3 million) showed accelerating bradyseism in 2023-24, raising concern about potential unrest from Europe's most hazardous volcano." },
    { id:"ss6-l3-24", level:3, question:"Assertion (A): Geothermal energy from volcanic zones is considered renewable.\nReason (R): The heat source (magma) is effectively inexhaustible on human timescales.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Geothermal energy is renewable because Earth's internal heat (from radioactive decay and primordial heat) will persist for billions of years." },
    { id:"ss6-l3-25", level:3, question:"Which correctly describes the global volcanic monitoring network?", options:["Only USGS monitors volcanoes","The Global Volcanism Program (Smithsonian) catalogues all eruptions; VAAC centres globally track ash clouds for aviation safety","Only affected countries monitor their volcanoes","There is no global system"], correctAnswer:1, explanation:"The Smithsonian's Global Volcanism Program (GVP) maintains the authoritative record; VAAC (Volcanic Ash Advisory Centres) coordinate international aviation hazard warnings." },
    { id:"ss6-l3-26", level:3, question:"Assertion (A): Volcanoes play a key role in Earth's long-term habitability.\nReason (R): Volcanic outgassing created Earth's early atmosphere and continues to recycle carbon and water from the mantle to the surface through the geological carbon cycle.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"Volcanic outgassing of CO₂, H₂O, and N₂ built Earth's primordial atmosphere and continues to drive the geological carbon cycle." },
    { id:"ss6-l3-27", level:3, question:"Volcanic Tourism (volcanotourism) raises which ethical concern?", options:["None — volcanoes are safe","Risk to life of tourists visiting active zones (Stromboli, Etna deaths) vs. economic benefit to local communities","It pollutes oceans","It is banned globally"], correctAnswer:1, explanation:"Volcanotourism deaths (Whakaari/White Island NZ 2019: 22 killed) highlight the tension between economic benefit and life-safety risk management." },
    { id:"ss6-l3-28", level:3, question:"Assertion (A): Continuous GPS monitoring of ground deformation is key to eruption prediction.\nReason (R): Rising magma inflates the overlying ground creating measurable surface uplift detectable weeks before eruptions.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"InSAR and GPS ground deformation monitoring is among the most reliable eruption precursor signals used by volcano observatories globally." },
    { id:"ss6-l3-29", level:3, question:"Which is a correct statement about India's geothermal energy potential?", options:["India has no geothermal resources","India has 7 geothermal provinces including Puga (J&K), Tattapani (Chhattisgarh), Manikaran (HP) with estimated 10,000 MW potential","India only has geothermal potential in Rajasthan","India uses geothermal for over 20% of its electricity"], correctAnswer:1, explanation:"India has identified 7 geothermal provinces with an estimated 10,000 MW potential; none are yet exploited for commercial electricity generation." },
    { id:"ss6-l3-30", level:3, question:"Assertion (A): Volcanic activity on Mars and Venus suggests Earth is not unique in its volcanism.\nReason (R): Recent NASA data (2023) confirmed active volcanic hotspots on Venus, while Olympus Mons on Mars is the solar system's largest volcano.", options:["Both true, R explains A","Both true, no explanation","A true R false","A false R true"], correctAnswer:0, explanation:"2023 NASA studies found evidence of recent Venus volcanism; Mars's Olympus Mons (21 km high, 600 km wide) dwarfs any Earth volcano." },
];
